    "examples" => "> SELECT cardinality(array('b', 'd', 'c', 'a'));\n4\n> SELECT cardinality(map('a', 1, 'b', 2));\n2",
    "note" => ""
  },
  "cbrt" => %{
    "usage" => "cbrt(expr) - Returns the cube root of `expr`.",
    "examples" => "> SELECT cbrt(27.0);\n3.0",
    "note" => ""
  },
  "ceil" => %{
    "usage" => "ceil(expr[, scale]) - Returns the smallest number after rounding up that is not smaller than `expr`. An optional `scale` parameter can be specified to control the rounding behavior.",
    "examples" => "> SELECT ceil(-0.1);\n0\n> SELECT ceil(5);\n5\n> SELECT ceil(3.1411, 3);\n3.142\n> SELECT ceil(3.1411, -3);\n1000",
    "note" => ""
  },
  "ceiling" => %{
    "usage" => "ceiling(expr[, scale]) - Returns the smallest number after rounding up that is not smaller than `expr`. An optional `scale` parameter can be specified to control the rounding behavior.",
    "examples" => "> SELECT ceiling(-0.1);\n0\n> SELECT ceiling(5);\n5\n> SELECT ceiling(3.1411, 3);\n3.142\n> SELECT ceiling(3.1411, -3);\n1000",
    "note" => ""
  },
  "char" => %{
    "usage" => "char(expr) - Returns the ASCII character having the binary equivalent to `expr`. If n is larger than 256 the result is equivalent to chr(n % 256)",
    "examples" => "> SELECT char(65);\nA",
    "note" => ""
  },
  "char_length" => %{
    "usage" => "char_length(expr) - Returns the character length of string data or number of bytes of binary data. The length of string data includes the trailing spaces. The length of binary data includes binary zeros.",
    "examples" => "> SELECT char_length('Spark SQL ');\n10\n> SELECT char_length(x'537061726b2053514c');\n9\n> SELECT CHAR_LENGTH('Spark SQL ');\n10\n> SELECT CHARACTER_LENGTH('Spark SQL ');\n10",
    "note" => ""
  },
  "character_length" => %{
    "usage" => "character_length(expr) - Returns the character length of string data or number of bytes of binary data. The length of string data includes the trailing spaces. The length of binary data includes binary zeros.",
    "examples" => "> SELECT character_length('Spark SQL ');\n10\n> SELECT character_length(x'537061726b2053514c');\n9\n> SELECT CHAR_LENGTH('Spark SQL ');\n10\n> SELECT CHARACTER_LENGTH('Spark SQL ');\n10",
    "note" => ""
  },
  "chr" => %{
    "usage" => "chr(expr) - Returns the ASCII character having the binary equivalent to `expr`. If n is larger than 256 the result is equivalent to chr(n % 256)",
    "examples" => "> SELECT chr(65);\nA",
    "note" => ""
  },
  "coalesce" => %{
    "usage" => "coalesce(expr1, expr2, ...) - Returns the first non-null argument if exists. Otherwise, null.",
    "examples" => "> SELECT coalesce(NULL, 1, NULL);\n1",
    "note" => ""
  },
  "collate" => %{
    "usage" => "collate(expr, collationName) - Marks a given expression with the specified collation.",
    "examples" => "> SELECT COLLATION('Spark SQL' collate UTF8_LCASE);\nSYSTEM.BUILTIN.UTF8_LCASE",
    "note" => ""
  },
  "collation" => %{
    "usage" => "collation(expr) - Returns the collation name of a given expression.",
    "examples" => "> SELECT collation('Spark SQL');\nSYSTEM.BUILTIN.UTF8_BINARY",
    "note" => ""
  },
  "collect_list" => %{
    "usage" => "collect_list(expr) - Collects and returns a list of non-unique elements.",
    "examples" => "> SELECT collect_list(col) FROM VALUES (1), (2), (1) AS tab(col);\n[1,2,1]",
    "note" => "The function is non-deterministic because the order of collected results depends\non the order of the rows which may be non-deterministic after a shuffle."
  },
  "collect_set" => %{
    "usage" => "collect_set(expr) - Collects and returns a set of unique elements.",
    "examples" => "> SELECT collect_set(col) FROM VALUES (1), (2), (1) AS tab(col);\n[1,2]",
    "note" => "The function is non-deterministic because the order of collected results depends\non the order of the rows which may be non-deterministic after a shuffle."
  },
  "concat" => %{
    "usage" => "concat(col1, col2, ..., colN) - Returns the concatenation of col1, col2, ..., colN.",
    "examples" => "> SELECT concat('Spark', 'SQL');\nSparkSQL\n> SELECT concat(array(1, 2, 3), array(4, 5), array(6));\n[1,2,3,4,5,6]",
    "note" => "Concat logic for arrays is available since 2.4.0."
  },
  "concat_ws" => %{
    "usage" => "concat_ws(sep[, str | array(str)]+) - Returns the concatenation of the strings separated by `sep`, skipping null values.",
    "examples" => "> SELECT concat_ws(' ', 'Spark', 'SQL');\nSpark SQL\n> SELECT concat_ws('s');\n> SELECT concat_ws('/', 'foo', null, 'bar');\nfoo/bar\n> SELECT concat_ws(null, 'Spark', 'SQL');\nNULL",
    "note" => ""
  },
  "conv" => %{
    "usage" => "conv(num, from_base, to_base) - Convert `num` from `from_base` to `to_base`.",
    "examples" => "> SELECT conv('100', 2, 10);\n4\n> SELECT conv(-10, 16, -10);\n-16",
    "note" => ""
  },
  "convert_timezone" => %{
    "usage" => "convert_timezone([sourceTz, ]targetTz, sourceTs) - Converts the timestamp without time zone `sourceTs` from the `sourceTz` time zone to `targetTz`.",
    "examples" => "> SELECT convert_timezone('Europe/Brussels', 'America/Los_Angeles', timestamp_ntz'2021-12-06 00:00:00');\n2021-12-05 15:00:00\n> SELECT convert_timezone('Europe/Brussels', timestamp_ntz'2021-12-05 15:00:00');\n2021-12-06 00:00:00",
    "note" => ""
  },
  "corr" => %{
    "usage" => "corr(expr1, expr2) - Returns Pearson coefficient of correlation between a set of number pairs.",
    "examples" => "> SELECT corr(c1, c2) FROM VALUES (3, 2), (3, 3), (6, 4) as tab(c1, c2);\n0.8660254037844387",
    "note" => ""
  },
  "cos" => %{
    "usage" => "cos(expr) - Returns the cosine of `expr`, as if computed by\n`java.lang.Math.cos`.",
    "examples" => "> SELECT cos(0);\n1.0",
    "note" => ""
  },
  "cosh" => %{
    "usage" => "cosh(expr) - Returns the hyperbolic cosine of `expr`, as if computed by\n`java.lang.Math.cosh`.",
    "examples" => "> SELECT cosh(0);\n1.0",
    "note" => ""
  },
  "cot" => %{
    "usage" => "cot(expr) - Returns the cotangent of `expr`, as if computed by `1/java.lang.Math.tan`.",
    "examples" => "> SELECT cot(1);\n0.6420926159343306",
    "note" => ""
  },
  "count" => %{
    "usage" => "count(*) - Returns the total number of retrieved rows, including rows containing null.\ncount(expr[, expr...]) - Returns the number of rows for which the supplied expression(s) are all non-null.\ncount(DISTINCT expr[, expr...]) - Returns the number of rows for which the supplied expression(s) are unique and non-null.",
    "examples" => "> SELECT count(*) FROM VALUES (NULL), (5), (5), (20) AS tab(col);\n4\n> SELECT count(col) FROM VALUES (NULL), (5), (5), (20) AS tab(col);\n3\n> SELECT count(DISTINCT col) FROM VALUES (NULL), (5), (5), (10) AS tab(col);\n2",
    "note" => ""
  },
  "count_if" => %{
    "usage" => "count_if(expr) - Returns the number of `TRUE` values for the expression.",
    "examples" => "> SELECT count_if(col % 2 = 0) FROM VALUES (NULL), (0), (1), (2), (3) AS tab(col);\n2\n> SELECT count_if(col IS NULL) FROM VALUES (NULL), (0), (1), (2), (3) AS tab(col);\n1",
    "note" => ""
  },
  "count_min_sketch" => %{
    "usage" => "count_min_sketch(col, eps, confidence, seed) - Returns a count-min sketch of a column with the given esp,\nconfidence and seed. The result is an array of bytes, which can be deserialized to a\n`CountMinSketch` before usage. Count-min sketch is a probabilistic data structure used for\ncardinality estimation using sub-linear space.",
    "examples" => "> SELECT hex(count_min_sketch(col, 0.5d, 0.5d, 1)) FROM VALUES (1), (2), (1) AS tab(col);\n0000000100000000000000030000000100000004000000005D8D6AB90000000000000000000000000000000200000000000000010000000000000000",
    "note" => ""
  },
  "covar_pop" => %{
    "usage" => "covar_pop(expr1, expr2) - Returns the population covariance of a set of number pairs.",
    "examples" => "> SELECT covar_pop(c1, c2) FROM VALUES (1,1), (2,2), (3,3) AS tab(c1, c2);\n0.6666666666666666",
    "note" => ""
  },
  "covar_samp" => %{
    "usage" => "covar_samp(expr1, expr2) - Returns the sample covariance of a set of number pairs.",
    "examples" => "> SELECT covar_samp(c1, c2) FROM VALUES (1,1), (2,2), (3,3) AS tab(c1, c2);\n1.0",
    "note" => ""
  },
  "crc32" => %{
    "usage" => "crc32(expr) - Returns a cyclic redundancy check value of the `expr` as a bigint.",
    "examples" => "> SELECT crc32('Spark');\n1557323817",
    "note" => ""
  },
  "csc" => %{
    "usage" => "csc(expr) - Returns the cosecant of `expr`, as if computed by `1/java.lang.Math.sin`.",
    "examples" => "> SELECT csc(1);\n1.1883951057781212",
    "note" => ""
  },
  "cume_dist" => %{
    "usage" => "cume_dist() - Computes the position of a value relative to all values in the partition.",
    "examples" => "> SELECT a, b, cume_dist() OVER (PARTITION BY a ORDER BY b) FROM VALUES ('A1', 2), ('A1', 1), ('A2', 3), ('A1', 1) tab(a, b);\nA1\t1\t0.6666666666666666\nA1\t1\t0.6666666666666666\nA1\t2\t1.0\nA2\t3\t1.0",
    "note" => ""
  },
  "curdate" => %{
    "usage" => "curdate() - Returns the current date at the start of query evaluation. All calls of curdate within the same query return the same value.",
    "examples" => "> SELECT curdate();\n2022-09-06",
    "note" => ""
  },
  "current_catalog" => %{
    "usage" => "current_catalog() - Returns the current catalog.",
    "examples" => "> SELECT current_catalog();\nspark_catalog",
    "note" => ""
  },
  "current_database" => %{
    "usage" => "current_database() - Returns the current database.",
    "examples" => "> SELECT current_database();\ndefault",
    "note" => ""
  },
  "current_date" => %{
    "usage" => "current_date() - Returns the current date at the start of query evaluation. All calls of current_date within the same query return the same value.\ncurrent_date - Returns the current date at the start of query evaluation.",
    "examples" => "> SELECT current_date();\n2020-04-25\n> SELECT current_date;\n2020-04-25",
    "note" => "The syntax without braces has been supported since 2.0.1."
  },
  "current_path" => %{
    "usage" => "current_path() - Returns the current SQL path (qualified schema names).",
    "examples" => "> SELECT current_path();\nsystem.builtin,system.session,spark_catalog.default",
    "note" => ""
  },
  "current_schema" => %{
    "usage" => "current_schema() - Returns the current database.",
    "examples" => "> SELECT current_schema();\ndefault",
    "note" => ""
  },
  "current_time" => %{
    "usage" => "current_time([precision]) - Returns the current time at the start of query evaluation.\nAll calls of current_time within the same query return the same value.\ncurrent_time - Returns the current time at the start of query evaluation.",
    "examples" => "> SELECT current_time();\n15:49:11.914120\n> SELECT current_time;\n15:49:11.914120\n> SELECT current_time(0);\n15:49:11\n> SELECT current_time(3);\n15:49:11.914\n> SELECT current_time(1+1);\n15:49:11.91",
    "note" => ""
  },
  "current_timestamp" => %{
    "usage" => "current_timestamp() - Returns the current timestamp at the start of query evaluation. All calls of current_timestamp within the same query return the same value.\ncurrent_timestamp - Returns the current timestamp at the start of query evaluation.",
    "examples" => "> SELECT current_timestamp();\n2020-04-25 15:49:11.914\n> SELECT current_timestamp;\n2020-04-25 15:49:11.914",
    "note" => "The syntax without braces has been supported since 2.0.1."
  },
  "current_timezone" => %{
    "usage" => "current_timezone() - Returns the current session local timezone.",
    "examples" => "> SELECT current_timezone();\nAsia/Shanghai",
    "note" => ""
  },
  "current_user" => %{
    "usage" => "current_user() - user name of current execution context.",
    "examples" => "> SELECT current_user();\nmockingjay",
    "note" => ""
  },
  "date_add" => %{
    "usage" => "date_add(start_date, num_days) - Returns the date that is `num_days` after `start_date`.",
    "examples" => "> SELECT date_add('2016-07-30', 1);\n2016-07-31",
    "note" => ""
  },
  "date_diff" => %{
    "usage" => "date_diff(endDate, startDate) - Returns the number of days from `startDate` to `endDate`.",
    "examples" => "> SELECT date_diff('2009-07-31', '2009-07-30');\n1\n> SELECT date_diff('2009-07-30', '2009-07-31');\n-1",
    "note" => ""
  },
  "date_format" => %{
    "usage" => "date_format(timestamp, fmt) - Converts `timestamp` to a value of string in the format specified by the date format `fmt`.",
    "examples" => "> SELECT date_format('2016-04-08', 'y');\n2016",
    "note" => ""
  },
  "date_from_unix_date" => %{
    "usage" => "date_from_unix_date(days) - Create date from the number of days since 1970-01-01.",
    "examples" => "> SELECT date_from_unix_date(1);\n1970-01-02",
    "note" => ""
  },
  "date_part" => %{
    "usage" => "date_part(field, source) - Extracts a part of the date/timestamp or interval source.",
    "examples" => "> SELECT date_part('YEAR', TIMESTAMP '2019-08-12 01:00:00.123456');\n2019\n> SELECT date_part('week', timestamp'2019-08-12 01:00:00.123456');\n33\n> SELECT date_part('doy', DATE'2019-08-12');\n224\n> SELECT date_part('SECONDS', timestamp'2019-10-01 00:00:01.000001');\n1.000001\n> SELECT date_part('days', interval 5 days 3 hours 7 minutes);\n5\n> SELECT date_part('seconds', interval 5 hours 30 seconds 1 milliseconds 1 microseconds);\n30.001001\n> SELECT date_part('MONTH', INTERVAL '2021-11' YEAR TO MONTH);\n11\n> SELECT date_part('MINUTE', INTERVAL '123 23:55:59.002001' DAY TO SECOND);\n55",
    "note" => "The date_part function is equivalent to the SQL-standard function `EXTRACT(field FROM source)`"
  },
  "date_sub" => %{
    "usage" => "date_sub(start_date, num_days) - Returns the date that is `num_days` before `start_date`.",
    "examples" => "> SELECT date_sub('2016-07-30', 1);\n2016-07-29",
    "note" => ""
  },
  "date_trunc" => %{
    "usage" => "date_trunc(fmt, ts) - Returns timestamp `ts` truncated to the unit specified by the format model `fmt`.",
    "examples" => "> SELECT date_trunc('YEAR', '2015-03-05T09:32:05.359');\n2015-01-01 00:00:00\n> SELECT date_trunc('MM', '2015-03-05T09:32:05.359');\n2015-03-01 00:00:00\n> SELECT date_trunc('DD', '2015-03-05T09:32:05.359');\n2015-03-05 00:00:00\n> SELECT date_trunc('HOUR', '2015-03-05T09:32:05.359');\n2015-03-05 09:00:00\n> SELECT date_trunc('MILLISECOND', '2015-03-05T09:32:05.123456');\n2015-03-05 09:32:05.123",
    "note" => ""
  },
  "dateadd" => %{
    "usage" => "dateadd(start_date, num_days) - Returns the date that is `num_days` after `start_date`.",
    "examples" => "> SELECT dateadd('2016-07-30', 1);\n2016-07-31",
    "note" => ""
  },
  "datediff" => %{
    "usage" => "datediff(endDate, startDate) - Returns the number of days from `startDate` to `endDate`.",
    "examples" => "> SELECT datediff('2009-07-31', '2009-07-30');\n1\n> SELECT datediff('2009-07-30', '2009-07-31');\n-1",
    "note" => ""
  },
  "datepart" => %{
    "usage" => "datepart(field, source) - Extracts a part of the date/timestamp or interval source.",
    "examples" => "> SELECT datepart('YEAR', TIMESTAMP '2019-08-12 01:00:00.123456');\n2019\n> SELECT datepart('week', timestamp'2019-08-12 01:00:00.123456');\n33\n> SELECT datepart('doy', DATE'2019-08-12');\n224\n> SELECT datepart('SECONDS', timestamp'2019-10-01 00:00:01.000001');\n1.000001\n> SELECT datepart('days', interval 5 days 3 hours 7 minutes);\n5\n> SELECT datepart('seconds', interval 5 hours 30 seconds 1 milliseconds 1 microseconds);\n30.001001\n> SELECT datepart('MONTH', INTERVAL '2021-11' YEAR TO MONTH);\n11\n> SELECT datepart('MINUTE', INTERVAL '123 23:55:59.002001' DAY TO SECOND);\n55",
    "note" => "The datepart function is equivalent to the SQL-standard function `EXTRACT(field FROM source)`"
  },
  "day" => %{
    "usage" => "day(date) - Returns the day of month of the date/timestamp.",
    "examples" => "> SELECT day('2009-07-30');\n30",
    "note" => ""
  },
  "dayname" => %{
    "usage" => "dayname(date) - Returns the three-letter abbreviated day name from the given date.",
    "examples" => "> SELECT dayname(DATE('2008-02-20'));\nWed",
    "note" => ""
  },
  "dayofmonth" => %{
    "usage" => "dayofmonth(date) - Returns the day of month of the date/timestamp.",
    "examples" => "> SELECT dayofmonth('2009-07-30');\n30",
    "note" => ""
  },
  "dayofweek" => %{
    "usage" => "dayofweek(date) - Returns the day of the week for date/timestamp (1 = Sunday, 2 = Monday, ..., 7 = Saturday).",
    "examples" => "> SELECT dayofweek('2009-07-30');\n5",
    "note" => ""
  },
  "dayofyear" => %{
    "usage" => "dayofyear(date) - Returns the day of year of the date/timestamp.",
    "examples" => "> SELECT dayofyear('2016-04-09');\n100",
    "note" => ""
  },
  "decode" => %{
    "usage" => "decode(bin, charset) - Decodes the first argument using the second argument character set. If either argument is null, the result will also be null.\ndecode(expr, search, result [, search, result ] ... [, default]) - Compares expr\nto each search value in order. If expr is equal to a search value, decode returns\nthe corresponding result. If no match is found, then it returns default. If default\nis omitted, it returns null.",
    "examples" => "> SELECT decode(encode('abc', 'utf-8'), 'utf-8');\nabc\n> SELECT decode(2, 1, 'Southlake', 2, 'San Francisco', 3, 'New Jersey', 4, 'Seattle', 'Non domestic');\nSan Francisco\n> SELECT decode(6, 1, 'Southlake', 2, 'San Francisco', 3, 'New Jersey', 4, 'Seattle', 'Non domestic');\nNon domestic\n> SELECT decode(6, 1, 'Southlake', 2, 'San Francisco', 3, 'New Jersey', 4, 'Seattle');\nNULL\n> SELECT decode(null, 6, 'Spark', NULL, 'SQL', 4, 'rocks');\nSQL",
    "note" => "decode(expr, search, result [, search, result ] ... [, default]) is supported since 3.2.0"
  },
  "degrees" => %{
    "usage" => "degrees(expr) - Converts radians to degrees.",
    "examples" => "> SELECT degrees(3.141592653589793);\n180.0",
    "note" => ""
  },
  "dense_rank" => %{
    "usage" => "dense_rank() - Computes the rank of a value in a group of values. The result is one plus the\npreviously assigned rank value. Unlike the function rank, dense_rank will not produce gaps\nin the ranking sequence.",
    "examples" => "> SELECT a, b, dense_rank(b) OVER (PARTITION BY a ORDER BY b) FROM VALUES ('A1', 2), ('A1', 1), ('A2', 3), ('A1', 1) tab(a, b);\nA1\t1\t1\nA1\t1\t1\nA1\t2\t2\nA2\t3\t1",
    "note" => ""
  },
  "e" => %{
    "usage" => "e() - Returns Euler's number, e.",
    "examples" => "> SELECT e();\n2.718281828459045",
    "note" => ""
  },
  "element_at" => %{
    "usage" => "element_at(array, index) - Returns element of array at given (1-based) index. If Index is 0,\nSpark will throw an error. If index < 0, accesses elements from the last to the first.\nThe function returns NULL if the index exceeds the length of the array and\n`spark.sql.ansi.enabled` is set to false.\nIf `spark.sql.ansi.enabled` is set to true, it throws ArrayIndexOutOfBoundsException\nfor invalid indices.\nelement_at(map, key) - Returns value for given key. The function returns NULL if the key is not\ncontained in the map.",
    "examples" => "> SELECT element_at(array(1, 2, 3), 2);\n2\n> SELECT element_at(map(1, 'a', 2, 'b'), 2);\nb",
    "note" => ""
  },
  "elt" => %{
    "usage" => "elt(n, input1, input2, ...) - Returns the `n`-th input, e.g., returns `input2` when `n` is 2.\nThe function returns NULL if the index exceeds the length of the array\nand `spark.sql.ansi.enabled` is set to false. If `spark.sql.ansi.enabled` is set to true,\nit throws ArrayIndexOutOfBoundsException for invalid indices.",
    "examples" => "> SELECT elt(1, 'scala', 'java');\nscala\n> SELECT elt(2, 'a', 1);\n1",
    "note" => ""
  },
  "encode" => %{
    "usage" => "encode(str, charset) - Encodes the first argument using the second argument character set. If either argument is null, the result will also be null.",
    "examples" => "> SELECT encode('abc', 'utf-8');\nabc",
    "note" => ""
  },
  "equal_null" => %{
    "usage" => "equal_null(expr1, expr2) - Returns same result as the EQUAL(=) operator for non-null operands,\nbut returns true if both are null, false if one of the them is null.",
    "examples" => "> SELECT equal_null(3, 3);\ntrue\n> SELECT equal_null(1, '11');\nfalse\n> SELECT equal_null(true, NULL);\nfalse\n> SELECT equal_null(NULL, 'abc');\nfalse\n> SELECT equal_null(NULL, NULL);\ntrue",
    "note" => ""
  },
  "every" => %{
    "usage" => "every(expr) - Returns true if all values of `expr` are true.",
    "examples" => "> SELECT every(col) FROM VALUES (true), (true), (true) AS tab(col);\ntrue\n> SELECT every(col) FROM VALUES (NULL), (true), (true) AS tab(col);\ntrue\n> SELECT every(col) FROM VALUES (true), (false), (true) AS tab(col);\nfalse",
    "note" => ""
  },
  "exists" => %{
    "usage" => "exists(expr, pred) - Tests whether a predicate holds for one or more elements in the array.",
    "examples" => "> SELECT exists(array(1, 2, 3), x -> x % 2 == 0);\ntrue\n> SELECT exists(array(1, 2, 3), x -> x % 2 == 10);\nfalse\n> SELECT exists(array(1, null, 3), x -> x % 2 == 0);\nNULL\n> SELECT exists(array(0, null, 2, 3, null), x -> x IS NULL);\ntrue\n> SELECT exists(array(1, 2, 3), x -> x IS NULL);\nfalse",
    "note" => ""
  },
  "exp" => %{
    "usage" => "exp(expr) - Returns e to the power of `expr`.",
    "examples" => "> SELECT exp(0);\n1.0",
    "note" => ""
  },
  "explode" => %{
    "usage" => "explode(expr) - Separates the elements of array `expr` into multiple rows, or the elements of map `expr` into multiple rows and columns. Unless specified otherwise, uses the default column name `col` for elements of the array or `key` and `value` for the elements of the map.",
    "examples" => "> SELECT explode(array(10, 20));\n10\n20\n> SELECT explode(collection => array(10, 20));\n10\n20",
    "note" => ""
  },
  "explode_outer" => %{
    "usage" => "explode_outer(expr) - Separates the elements of array `expr` into multiple rows, or the elements of map `expr` into multiple rows and columns. Unless specified otherwise, uses the default column name `col` for elements of the array or `key` and `value` for the elements of the map.",
    "examples" => "> SELECT explode_outer(array(10, 20));\n10\n20\n> SELECT explode_outer(collection => array(10, 20));\n10\n20",
    "note" => ""
  },
  "expm1" => %{
    "usage" => "expm1(expr) - Returns exp(`expr`) - 1.",
    "examples" => "> SELECT expm1(0);\n0.0",
    "note" => ""
  },
  "extract" => %{
    "usage" => "extract(field FROM source) - Extracts a part of the date or timestamp or time or interval source.",
    "examples" => "> SELECT extract(YEAR FROM TIMESTAMP '2019-08-12 01:00:00.123456');\n2019\n> SELECT extract(week FROM timestamp'2019-08-12 01:00:00.123456');\n33\n> SELECT extract(doy FROM DATE'2019-08-12');\n224\n> SELECT extract(SECONDS FROM timestamp'2019-10-01 00:00:01.000001');\n1.000001\n> SELECT extract(days FROM interval 5 days 3 hours 7 minutes);\n5\n> SELECT extract(seconds FROM interval 5 hours 30 seconds 1 milliseconds 1 microseconds);\n30.001001\n> SELECT extract(MONTH FROM INTERVAL '2021-11' YEAR TO MONTH);\n11\n> SELECT extract(MINUTE FROM INTERVAL '123 23:55:59.002001' DAY TO SECOND);\n55\n> SELECT extract(HOUR FROM time '09:08:01.000001');\n9\n> SELECT extract(MINUTE FROM time '09:08:01.000001');\n8\n> SELECT extract(SECOND FROM time '09:08:01.000001');\n1.000001",
    "note" => "The extract function is equivalent to `date_part(field, source)`."
  },
  "factorial" => %{
    "usage" => "factorial(expr) - Returns the factorial of `expr`. `expr` is [0..20]. Otherwise, null.",
    "examples" => "> SELECT factorial(5);\n120",
    "note" => ""
  },
  "filter" => %{
    "usage" => "filter(expr, func) - Filters the input array using the given predicate.",
    "examples" => "> SELECT filter(array(1, 2, 3), x -> x % 2 == 1);\n[1,3]\n> SELECT filter(array(0, 2, 3), (x, i) -> x > i);\n[2,3]\n> SELECT filter(array(0, null, 2, 3, null), x -> x IS NOT NULL);\n[0,2,3]",
    "note" => "The inner function may use the index argument since 3.0.0."
  },
  "find_in_set" => %{
    "usage" => "find_in_set(str, str_array) - Returns the index (1-based) of the given string (`str`) in the comma-delimited list (`str_array`).\nReturns 0, if the string was not found or if the given string (`str`) contains a comma.",
    "examples" => "> SELECT find_in_set('ab','abc,b,ab,c,def');\n3",
    "note" => ""
  },
  "first" => %{
    "usage" => "first(expr[, isIgnoreNull]) - Returns the first value of `expr` for a group of rows.\nIf `isIgnoreNull` is true, returns only non-null values.",
    "examples" => "> SELECT first(col) FROM VALUES (10), (5), (20) AS tab(col);\n10\n> SELECT first(col) FROM VALUES (NULL), (5), (20) AS tab(col);\nNULL\n> SELECT first(col, true) FROM VALUES (NULL), (5), (20) AS tab(col);\n5",
    "note" => "The function is non-deterministic because its results depends on the order of the rows\nwhich may be non-deterministic after a shuffle."
  },
  "first_value" => %{
    "usage" => "first_value(expr[, isIgnoreNull]) - Returns the first value of `expr` for a group of rows.\nIf `isIgnoreNull` is true, returns only non-null values.",
    "examples" => "> SELECT first_value(col) FROM VALUES (10), (5), (20) AS tab(col);\n10\n> SELECT first_value(col) FROM VALUES (NULL), (5), (20) AS tab(col);\nNULL\n> SELECT first_value(col, true) FROM VALUES (NULL), (5), (20) AS tab(col);\n5",
    "note" => "The function is non-deterministic because its results depends on the order of the rows\nwhich may be non-deterministic after a shuffle."
  },
  "flatten" => %{
    "usage" => "flatten(arrayOfArrays) - Transforms an array of arrays into a single array.",
    "examples" => "> SELECT flatten(array(array(1, 2), array(3, 4)));\n[1,2,3,4]",
    "note" => ""
  },
  "floor" => %{
    "usage" => "floor(expr[, scale]) - Returns the largest number after rounding down that is not greater than `expr`. An optional `scale` parameter can be specified to control the rounding behavior.",
    "examples" => "> SELECT floor(-0.1);\n-1\n> SELECT floor(5);\n5\n> SELECT floor(3.1411, 3);\n3.141\n> SELECT floor(3.1411, -3);\n0",
    "note" => ""
  },
  "forall" => %{
    "usage" => "forall(expr, pred) - Tests whether a predicate holds for all elements in the array.",
    "examples" => "> SELECT forall(array(1, 2, 3), x -> x % 2 == 0);\nfalse\n> SELECT forall(array(2, 4, 8), x -> x % 2 == 0);\ntrue\n> SELECT forall(array(1, null, 3), x -> x % 2 == 0);\nfalse\n> SELECT forall(array(2, null, 8), x -> x % 2 == 0);\nNULL",
    "note" => ""
  },
  "format_number" => %{
    "usage" => "format_number(expr1, expr2) - Formats the number `expr1` like '#,###,###.##', rounded to `expr2`\ndecimal places. If `expr2` is 0, the result has no decimal point or fractional part.\n`expr2` also accept a user specified format.\nThis is supposed to function like MySQL's FORMAT.",
    "examples" => "> SELECT format_number(12332.123456, 4);\n12,332.1235\n> SELECT format_number(12332.123456, '##################.###');\n12332.123",
    "note" => ""
  },
  "format_string" => %{
    "usage" => "format_string(strfmt, obj, ...) - Returns a formatted string from printf-style format strings.",
    "examples" => "> SELECT format_string(\"Hello World %d %s\", 100, \"days\");\nHello World 100 days",
    "note" => ""
  },
  "from_csv" => %{
    "usage" => "from_csv(csvStr, schema[, options]) - Returns a struct value with the given `csvStr` and `schema`.",
    "examples" => "> SELECT from_csv('1, 0.8', 'a INT, b DOUBLE');\n{\"a\":1,\"b\":0.8}\n> SELECT from_csv('26/08/2015', 'time Timestamp', map('timestampFormat', 'dd/MM/yyyy'));\n{\"time\":2015-08-26 00:00:00}",
    "note" => ""
  },
  "from_json" => %{
    "usage" => "from_json(jsonStr, schema[, options]) - Returns a struct value with the given `jsonStr` and `schema`.",
    "examples" => "> SELECT from_json('{\"a\":1, \"b\":0.8}', 'a INT, b DOUBLE');\n{\"a\":1,\"b\":0.8}\n> SELECT from_json('{\"time\":\"26/08/2015\"}', 'time Timestamp', map('timestampFormat', 'dd/MM/yyyy'));\n{\"time\":2015-08-26 00:00:00}\n> SELECT from_json('{\"teacher\": \"Alice\", \"student\": [{\"name\": \"Bob\", \"rank\": 1}, {\"name\": \"Charlie\", \"rank\": 2}]}', 'STRUCT<teacher: STRING, student: ARRAY<STRUCT<name: STRING, rank: INT>>>');\n{\"teacher\":\"Alice\",\"student\":[{\"name\":\"Bob\",\"rank\":1},{\"name\":\"Charlie\",\"rank\":2}]}",
    "note" => ""
  },
  "from_unixtime" => %{
    "usage" => "from_unixtime(unix_time[, fmt]) - Returns `unix_time` in the specified `fmt`.",
    "examples" => "> SELECT from_unixtime(0, 'yyyy-MM-dd HH:mm:ss');\n1969-12-31 16:00:00\n> SELECT from_unixtime(0);\n1969-12-31 16:00:00",
    "note" => ""
  },
  "from_utc_timestamp" => %{
    "usage" => "from_utc_timestamp(timestamp, timezone) - Given a timestamp like '2017-07-14 02:40:00.0', interprets it as a time in UTC, and renders that time as a timestamp in the given time zone. For example, 'GMT+1' would yield '2017-07-14 03:40:00.0'.",
    "examples" => "> SELECT from_utc_timestamp('2016-08-31', 'Asia/Seoul');\n2016-08-31 09:00:00",
    "note" => ""
  },
  "from_xml" => %{
    "usage" => "from_xml(xmlStr, schema[, options]) - Returns a struct value with the given `xmlStr` and `schema`.",
    "examples" => "> SELECT from_xml('<p><a>1</a><b>0.8</b></p>', 'a INT, b DOUBLE');\n{\"a\":1,\"b\":0.8}\n> SELECT from_xml('<p><time>26/08/2015</time></p>', 'time Timestamp', map('timestampFormat', 'dd/MM/yyyy'));\n{\"time\":2015-08-26 00:00:00}\n> SELECT from_xml('<p><teacher>Alice</teacher><student><name>Bob</name><rank>1</rank></student><student><name>Charlie</name><rank>2</rank></student></p>', 'STRUCT<teacher: STRING, student: ARRAY<STRUCT<name: STRING, rank: INT>>>');\n{\"teacher\":\"Alice\",\"student\":[{\"name\":\"Bob\",\"rank\":1},{\"name\":\"Charlie\",\"rank\":2}]}",
    "note" => ""
  },
  "get" => %{
    "usage" => "get(array, index) - Returns element of array at given (0-based) index. If the index points\noutside of the array boundaries, then this function returns NULL.",
    "examples" => "> SELECT get(array(1, 2, 3), 0);\n1\n> SELECT get(array(1, 2, 3), 3);\nNULL\n> SELECT get(array(1, 2, 3), -1);\nNULL",
    "note" => ""
  },
  "get_json_object" => %{
    "usage" => "get_json_object(json_txt, path) - Extracts a json object from `path`.",
    "examples" => "> SELECT get_json_object('{\"a\":\"b\"}', '$.a');\nb\n> SELECT get_json_object('[{\"a\":\"b\"},{\"a\":\"c\"}]', '$[0].a');\nb\n> SELECT get_json_object('[{\"a\":\"b\"},{\"a\":\"c\"}]', '$[*].a');\n[\"b\",\"c\"]",
    "note" => ""
  },
  "getbit" => %{
    "usage" => "getbit(expr, pos) - Returns the value of the bit (0 or 1) at the specified position.\nThe positions are numbered from right to left, starting at zero.\nThe position argument cannot be negative.",
    "examples" => "> SELECT getbit(11, 0);\n1\n> SELECT getbit(11, 2);\n0",
    "note" => ""
  },
  "greatest" => %{
    "usage" => "greatest(expr, ...) - Returns the greatest value of all parameters, skipping null values.",
    "examples" => "> SELECT greatest(10, 9, 2, 4, 3);\n10",
    "note" => ""
  },
  "grouping" => %{
    "usage" => "grouping(col) - indicates whether a specified column in a GROUP BY is aggregated or\nnot, returns 1 for aggregated or 0 for not aggregated in the result set.\",",
    "examples" => "> SELECT name, grouping(name), sum(age) FROM VALUES (2, 'Alice'), (5, 'Bob') people(age, name) GROUP BY cube(name);\nAlice\t0\t2\nBob\t0\t5\nNULL\t1\t7",
    "note" => ""
  },
  "grouping_id" => %{
    "usage" => "grouping_id([col1[, col2 ..]]) - returns the level of grouping, equals to\n`(grouping(c1) << (n-1)) + (grouping(c2) << (n-2)) + ... + grouping(cn)`",
    "examples" => "> SELECT name, grouping_id(), sum(age), avg(height) FROM VALUES (2, 'Alice', 165), (5, 'Bob', 180) people(age, name, height) GROUP BY cube(name, height);\nAlice\t0\t2\t165.0\nAlice\t1\t2\t165.0\nNULL\t3\t7\t172.5\nBob\t0\t5\t180.0\nBob\t1\t5\t180.0\nNULL\t2\t2\t165.0\nNULL\t2\t5\t180.0",
    "note" => "Input columns should match with grouping columns exactly, or empty (means all the grouping\ncolumns)."
  },
  "hash" => %{
    "usage" => "hash(expr1, expr2, ...) - Returns a hash value of the arguments.",
    "examples" => "> SELECT hash('Spark', array(123), 2);\n-1321691492",
    "note" => ""
  },
  "hex" => %{
    "usage" => "hex(expr) - Converts `expr` to hexadecimal.",
    "examples" => "> SELECT hex(17);\n11\n> SELECT hex('Spark SQL');\n537061726B2053514C",
    "note" => ""
  },
  "histogram_numeric" => %{
    "usage" => "histogram_numeric(expr, nb) - Computes a histogram on numeric 'expr' using nb bins.\nThe return value is an array of (x,y) pairs representing the centers of the\nhistogram's bins. As the value of 'nb' is increased, the histogram approximation\ngets finer-grained, but may yield artifacts around outliers. In practice, 20-40\nhistogram bins appear to work well, with more bins being required for skewed or\nsmaller datasets. Note that this function creates a histogram with non-uniform\nbin widths. It offers no guarantees in terms of the mean-squared-error of the\nhistogram, but in practice is comparable to the histograms produced by the R/S-Plus\nstatistical computing packages. Note: the output type of the 'x' field in the return value is\npropagated from the input value consumed in the aggregate function.",
    "examples" => "> SELECT histogram_numeric(col, 5) FROM VALUES (0), (1), (2), (10) AS tab(col);\n[{\"x\":0,\"y\":1.0},{\"x\":1,\"y\":1.0},{\"x\":2,\"y\":1.0},{\"x\":10,\"y\":1.0}]",
    "note" => ""
  },
  "hll_sketch_agg" => %{
    "usage" => "hll_sketch_agg(expr, lgConfigK) - Returns the HllSketch's updatable binary representation.\n`lgConfigK` (optional) the log-base-2 of K, with K is the number of buckets or\nslots for the HllSketch.",
    "examples" => "> SELECT hll_sketch_estimate(hll_sketch_agg(col, 12)) FROM VALUES (1), (1), (2), (2), (3) tab(col);\n3",
    "note" => ""
  },
  "hll_sketch_estimate" => %{
    "usage" => "hll_sketch_estimate(expr) - Returns the estimated number of unique values given the binary representation\nof a Datasketches HllSketch.",
    "examples" => "> SELECT hll_sketch_estimate(hll_sketch_agg(col)) FROM VALUES (1), (1), (2), (2), (3) tab(col);\n3",
    "note" => ""
  },
  "hll_union" => %{
    "usage" => "hll_union(first, second, allowDifferentLgConfigK) - Merges two binary representations of\nDatasketches HllSketch objects, using a Datasketches Union object. Set\nallowDifferentLgConfigK to true to allow unions of sketches with different\nlgConfigK values (defaults to false).",
    "examples" => "> SELECT hll_sketch_estimate(hll_union(hll_sketch_agg(col1), hll_sketch_agg(col2))) FROM VALUES (1, 4), (1, 4), (2, 5), (2, 5), (3, 6) tab(col1, col2);\n6",
    "note" => ""
  },
  "hll_union_agg" => %{
    "usage" => "hll_union_agg(expr, allowDifferentLgConfigK) - Returns the estimated number of unique values.\n`allowDifferentLgConfigK` (optional) Allow sketches with different lgConfigK values\nto be unioned (defaults to false).",
    "examples" => "> SELECT hll_sketch_estimate(hll_union_agg(sketch, true)) FROM (SELECT hll_sketch_agg(col) as sketch FROM VALUES (1) tab(col) UNION ALL SELECT hll_sketch_agg(col, 20) as sketch FROM VALUES (1) tab(col));\n1",
    "note" => ""
  },
  "hour" => %{
    "usage" => "hour(expr) - Returns the hour component of the given expression.\nIf `expr` is a TIMESTAMP or a string that can be cast to timestamp,\nit returns the hour of that timestamp.\nIf `expr` is a TIME type (since 4.1.0), it returns the hour of the time-of-day.",
    "examples" => "> SELECT hour('2018-02-14 12:58:59');\n12\n> SELECT hour(TIME'13:59:59.999999');\n13",
    "note" => ""
  },
  "hypot" => %{
    "usage" => "hypot(expr1, expr2) - Returns sqrt(`expr1`² + `expr2`²).",
    "examples" => "> SELECT hypot(3, 4);\n5.0",
    "note" => ""
  },
  "ifnull" => %{
    "usage" => "ifnull(expr1, expr2) - Returns `expr2` if `expr1` is null, or `expr1` otherwise.",
    "examples" => "> SELECT ifnull(NULL, array('2'));\n[\"2\"]",
    "note" => ""
  },
  "initcap" => %{
    "usage" => "initcap(str) - Returns `str` with the first letter of each word in uppercase.\nAll other letters are in lowercase. Words are delimited by white space.",
    "examples" => "> SELECT initcap('sPark sql');\nSpark Sql",
    "note" => ""
  },
  "inline" => %{
    "usage" => "inline(expr) - Explodes an array of structs into a table. Uses column names col1, col2, etc. by default unless specified otherwise.",
    "examples" => "> SELECT inline(array(struct(1, 'a'), struct(2, 'b')));\n1\ta\n2\tb\n> SELECT inline(input => array(struct(1, 'a'), struct(2, 'b')));\n1\ta\n2\tb",
    "note" => ""
  },
  "inline_outer" => %{
    "usage" => "inline_outer(expr) - Explodes an array of structs into a table. Uses column names col1, col2, etc. by default unless specified otherwise.",
    "examples" => "> SELECT inline_outer(array(struct(1, 'a'), struct(2, 'b')));\n1\ta\n2\tb\n> SELECT inline_outer(input => array(struct(1, 'a'), struct(2, 'b')));\n1\ta\n2\tb",
    "note" => ""
  },
  "input_file_block_length" => %{
    "usage" => "input_file_block_length() - Returns the length of the block being read, or -1 if not available.",
    "examples" => "> SELECT input_file_block_length();\n-1",
    "note" => ""
  },
  "input_file_block_start" => %{
    "usage" => "input_file_block_start() - Returns the start offset of the block being read, or -1 if not available.",
    "examples" => "> SELECT input_file_block_start();\n-1",
    "note" => ""
  },
  "input_file_name" => %{
    "usage" => "input_file_name() - Returns the name of the file being read, or empty string if not available.",
    "examples" => "> SELECT input_file_name();",
    "note" => ""
  },
  "instr" => %{
    "usage" => "instr(str, substr) - Returns the (1-based) index of the first occurrence of `substr` in `str`.",
    "examples" => "> SELECT instr('SparkSQL', 'SQL');\n6",
    "note" => ""
  },
  "is_valid_utf8" => %{
    "usage" => "is_valid_utf8(str) - Returns true if `str` is a valid UTF-8 string, otherwise returns false.",
    "examples" => "> SELECT is_valid_utf8('Spark');\ntrue\n> SELECT is_valid_utf8(x'61');\ntrue\n> SELECT is_valid_utf8(x'80');\nfalse\n> SELECT is_valid_utf8(x'61C262');\nfalse",
    "note" => ""
  },
  "is_valid_variant" => %{
    "usage" => "is_valid_variant(v) - Returns true if the variant is valid, false if it is malformed, NULL if `v` is NULL.",
    "examples" => "> SELECT is_valid_variant(parse_json('null'));\ntrue\n> SELECT is_valid_variant(parse_json('[{\"b\":true,\"a\":0}]'));\ntrue",
    "note" => ""
  },
  "is_variant_null" => %{
    "usage" => "is_variant_null(expr) - Check if a variant value is a variant null. Returns true if and only if the input is a variant null and false otherwise (including in the case of SQL NULL).",
    "examples" => "> SELECT is_variant_null(parse_json('null'));\ntrue\n> SELECT is_variant_null(parse_json('\"null\"'));\nfalse\n> SELECT is_variant_null(parse_json('13'));\nfalse\n> SELECT is_variant_null(parse_json(null));\nfalse\n> SELECT is_variant_null(variant_get(parse_json('{\"a\":null, \"b\":\"spark\"}'), \"$.c\"));\nfalse\n> SELECT is_variant_null(variant_get(parse_json('{\"a\":null, \"b\":\"spark\"}'), \"$.a\"));\ntrue",
    "note" => ""
  },
  "java_method" => %{
    "usage" => "java_method(class, method[, arg1[, arg2 ..]]) - Calls a method with reflection.",
    "examples" => "> SELECT java_method('java.util.UUID', 'randomUUID');\nc33fb387-8500-4bfa-81d2-6e0e3e930df2\n> SELECT java_method('java.util.UUID', 'fromString', 'a5cf6c42-0c85-418f-af6c-3e4e5b1328f2');\na5cf6c42-0c85-418f-af6c-3e4e5b1328f2",
    "note" => ""
  },
  "json_array_length" => %{
    "usage" => "json_array_length(jsonArray) - Returns the number of elements in the outermost JSON array.",
    "examples" => "> SELECT json_array_length('[1,2,3,4]');\n4\n> SELECT json_array_length('[1,2,3,{\"f1\":1,\"f2\":[5,6]},4]');\n5\n> SELECT json_array_length('[1,2');\nNULL",
    "note" => ""
  },
  "json_object_keys" => %{
    "usage" => "json_object_keys(json_object) - Returns all the keys of the outermost JSON object as an array.",
    "examples" => "> SELECT json_object_keys('{}');\n[]\n> SELECT json_object_keys('{\"key\": \"value\"}');\n[\"key\"]\n> SELECT json_object_keys('{\"f1\":\"abc\",\"f2\":{\"f3\":\"a\", \"f4\":\"b\"}}');\n[\"f1\",\"f2\"]",
    "note" => ""
  },
  "json_tuple" => %{
    "usage" => "json_tuple(jsonStr, p1, p2, ..., pn) - Returns a tuple like the function get_json_object, but it takes multiple names. All the input parameters and output column types are string.",
    "examples" => "> SELECT json_tuple('{\"a\":1, \"b\":2}', 'a', 'b');\n1\t2",
    "note" => ""
  },
  "kurtosis" => %{
    "usage" => "kurtosis(expr) - Returns the kurtosis value calculated from values of a group.",
    "examples" => "> SELECT kurtosis(col) FROM VALUES (-10), (-20), (100), (1000) AS tab(col);\n-0.7014368047529627\n> SELECT kurtosis(col) FROM VALUES (1), (10), (100), (10), (1) as tab(col);\n0.19432323191699075",
    "note" => ""
  },
  "lag" => %{
    "usage" => "lag(input[, offset[, default]]) - Returns the value of `input` at the `offset`th row\nbefore the current row in the window. The default value of `offset` is 1 and the default\nvalue of `default` is null. If the value of `input` at the `offset`th row is null,\nnull is returned. If there is no such offset row (e.g., when the offset is 1, the first\nrow of the window does not have any previous row), `default` is returned.",
    "examples" => "> SELECT a, b, lag(b) OVER (PARTITION BY a ORDER BY b) FROM VALUES ('A1', 2), ('A1', 1), ('A2', 3), ('A1', 1) tab(a, b);\nA1\t1\tNULL\nA1\t1\t1\nA1\t2\t1\nA2\t3\tNULL",
    "note" => ""
  },
  "last" => %{
    "usage" => "last(expr[, isIgnoreNull]) - Returns the last value of `expr` for a group of rows.\nIf `isIgnoreNull` is true, returns only non-null values",
    "examples" => "> SELECT last(col) FROM VALUES (10), (5), (20) AS tab(col);\n20\n> SELECT last(col) FROM VALUES (10), (5), (NULL) AS tab(col);\nNULL\n> SELECT last(col, true) FROM VALUES (10), (5), (NULL) AS tab(col);\n5",
    "note" => "The function is non-deterministic because its results depends on the order of the rows\nwhich may be non-deterministic after a shuffle."
  },
  "last_day" => %{
    "usage" => "last_day(date) - Returns the last day of the month which the date belongs to.",
    "examples" => "> SELECT last_day('2009-01-12');\n2009-01-31",
    "note" => ""
  },
  "last_value" => %{
    "usage" => "last_value(expr[, isIgnoreNull]) - Returns the last value of `expr` for a group of rows.\nIf `isIgnoreNull` is true, returns only non-null values",
    "examples" => "> SELECT last_value(col) FROM VALUES (10), (5), (20) AS tab(col);\n20\n> SELECT last_value(col) FROM VALUES (10), (5), (NULL) AS tab(col);\nNULL\n> SELECT last_value(col, true) FROM VALUES (10), (5), (NULL) AS tab(col);\n5",
    "note" => "The function is non-deterministic because its results depends on the order of the rows\nwhich may be non-deterministic after a shuffle."
  },
  "lcase" => %{
    "usage" => "lcase(str) - Returns `str` with all characters changed to lowercase.",
    "examples" => "> SELECT lcase('SparkSql');\nsparksql",
    "note" => ""
  },
  "lead" => %{
    "usage" => "lead(input[, offset[, default]]) - Returns the value of `input` at the `offset`th row\nafter the current row in the window. The default value of `offset` is 1 and the default\nvalue of `default` is null. If the value of `input` at the `offset`th row is null,\nnull is returned. If there is no such an offset row (e.g., when the offset is 1, the last\nrow of the window does not have any subsequent row), `default` is returned.",
    "examples" => "> SELECT a, b, lead(b) OVER (PARTITION BY a ORDER BY b) FROM VALUES ('A1', 2), ('A1', 1), ('A2', 3), ('A1', 1) tab(a, b);\nA1\t1\t1\nA1\t1\t2\nA1\t2\tNULL\nA2\t3\tNULL",
    "note" => ""
  },
  "least" => %{
    "usage" => "least(expr, ...) - Returns the least value of all parameters, skipping null values.",
    "examples" => "> SELECT least(10, 9, 2, 4, 3);\n2",
    "note" => ""
  },
  "left" => %{
    "usage" => "left(str, len) - Returns the leftmost `len`(`len` can be string type) characters from the string `str`,if `len` is less or equal than 0 the result is an empty string.",
    "examples" => "> SELECT left('Spark SQL', 3);\nSpa\n> SELECT left(encode('Spark SQL', 'utf-8'), 3);\nSpa",
    "note" => ""
  },
  "length" => %{
    "usage" => "length(expr) - Returns the character length of string data or number of bytes of binary data. The length of string data includes the trailing spaces. The length of binary data includes binary zeros.",
    "examples" => "> SELECT length('Spark SQL ');\n10\n> SELECT length(x'537061726b2053514c');\n9\n> SELECT CHAR_LENGTH('Spark SQL ');\n10\n> SELECT CHARACTER_LENGTH('Spark SQL ');\n10",
    "note" => ""
  },
  "levenshtein" => %{
    "usage" => "levenshtein(str1, str2[, threshold]) - Returns the Levenshtein distance between the two given strings. If threshold is set and distance more than it, return -1.",
    "examples" => "> SELECT levenshtein('kitten', 'sitting');\n3\n> SELECT levenshtein('kitten', 'sitting', 2);\n-1",
    "note" => ""
  },
  "listagg" => %{
    "usage" => "listagg(expr[, delimiter])[ WITHIN GROUP (ORDER BY key [ASC | DESC] [,...])] - Returns\nthe concatenation of non-NULL input values, separated by the delimiter ordered by key.\nIf all values are NULL, NULL is returned.",
    "examples" => "> SELECT listagg(col) FROM VALUES ('a'), ('b'), ('c') AS tab(col);\nabc\n> SELECT listagg(col) WITHIN GROUP (ORDER BY col DESC) FROM VALUES ('a'), ('b'), ('c') AS tab(col);\ncba\n> SELECT listagg(col) FROM VALUES ('a'), (NULL), ('b') AS tab(col);\nab\n> SELECT listagg(col) FROM VALUES ('a'), ('a') AS tab(col);\naa\n> SELECT listagg(DISTINCT col) FROM VALUES ('a'), ('a'), ('b') AS tab(col);\nab\n> SELECT listagg(col, ', ') FROM VALUES ('a'), ('b'), ('c') AS tab(col);\na, b, c\n> SELECT listagg(col) FROM VALUES (NULL), (NULL) AS tab(col);\nNULL",
    "note" => "* If the order is not specified, the function is non-deterministic because\nthe order of the rows may be non-deterministic after a shuffle.\n* If DISTINCT is specified, then expr and key must be the same expression."
  },
  "ln" => %{
    "usage" => "ln(expr) - Returns the natural logarithm (base e) of `expr`.",
    "examples" => "> SELECT ln(1);\n0.0",
    "note" => ""
  },
  "localtimestamp" => %{
    "usage" => "localtimestamp() - Returns the current timestamp without time zone at the start of query evaluation. All calls of localtimestamp within the same query return the same value.\nlocaltimestamp - Returns the current local date-time at the session time zone at the start of query evaluation.",
    "examples" => "> SELECT localtimestamp();\n2020-04-25 15:49:11.914",
    "note" => ""
  },
  "locate" => %{
    "usage" => "locate(substr, str[, pos]) - Returns the position of the first occurrence of `substr` in `str` after position `pos`.\nThe given `pos` and return value are 1-based.",
    "examples" => "> SELECT locate('bar', 'foobarbar');\n4\n> SELECT locate('bar', 'foobarbar', 5);\n7\n> SELECT POSITION('bar' IN 'foobarbar');\n4",
    "note" => ""
  },
  "log10" => %{
    "usage" => "log10(expr) - Returns the logarithm of `expr` with base 10.",
    "examples" => "> SELECT log10(10);\n1.0",
    "note" => ""
  },
  "log1p" => %{
    "usage" => "log1p(expr) - Returns log(1 + `expr`).",
    "examples" => "> SELECT log1p(0);\n0.0",
    "note" => ""
  },
  "log2" => %{
    "usage" => "log2(expr) - Returns the logarithm of `expr` with base 2.",
    "examples" => "> SELECT log2(2);\n1.0",
    "note" => ""
  },
  "lower" => %{
    "usage" => "lower(str) - Returns `str` with all characters changed to lowercase.",
    "examples" => "> SELECT lower('SparkSql');\nsparksql",
    "note" => ""
  },
  "lpad" => %{
    "usage" => "lpad(str, len[, pad]) - Returns `str`, left-padded with `pad` to a length of `len`.\nIf `str` is longer than `len`, the return value is shortened to `len` characters or bytes.\nIf `pad` is not specified, `str` will be padded to the left with space characters if it is\na character string, and with zeros if it is a byte sequence.",
    "examples" => "> SELECT lpad('hi', 5, '??');\n???hi\n> SELECT lpad('hi', 1, '??');\nh\n> SELECT lpad('hi', 5);\nhi\n> SELECT hex(lpad(unhex('aabb'), 5));\n000000AABB\n> SELECT hex(lpad(unhex('aabb'), 5, unhex('1122')));\n112211AABB",
    "note" => ""
  },
  "ltrim" => %{
    "usage" => "ltrim(str) - Removes the leading space characters from `str`.",
    "examples" => "> SELECT ltrim('    SparkSQL   ');\nSparkSQL",
    "note" => ""
  },
  "make_date" => %{
    "usage" => "make_date(year, month, day) - Create date from year, month and day fields. If the configuration `spark.sql.ansi.enabled` is false, the function returns NULL on invalid inputs. Otherwise, it will throw an error instead.",
    "examples" => "> SELECT make_date(2013, 7, 15);\n2013-07-15\n> SELECT make_date(2019, 7, NULL);\nNULL",
    "note" => ""
  },
  "make_dt_interval" => %{
    "usage" => "make_dt_interval([days[, hours[, mins[, secs]]]]) - Make DayTimeIntervalType duration from days, hours, mins and secs.",
    "examples" => "> SELECT make_dt_interval(1, 12, 30, 01.001001);\n1 12:30:01.001001000\n> SELECT make_dt_interval(2);\n2 00:00:00.000000000\n> SELECT make_dt_interval(100, null, 3);\nNULL",
    "note" => ""
  },
  "make_interval" => %{
    "usage" => "make_interval([years[, months[, weeks[, days[, hours[, mins[, secs]]]]]]]) - Make interval from years, months, weeks, days, hours, mins and secs.",
    "examples" => "> SELECT make_interval(100, 11, 1, 1, 12, 30, 01.001001);\n100 years 11 months 8 days 12 hours 30 minutes 1.001001 seconds\n> SELECT make_interval(100, null, 3);\nNULL\n> SELECT make_interval(0, 1, 0, 1, 0, 0, 100.000001);\n1 months 1 days 1 minutes 40.000001 seconds",
    "note" => ""
  },
  "make_time" => %{
    "usage" => "make_time(hour, minute, second) - Create time from hour, minute and second fields. For invalid inputs it will throw an error.",
    "examples" => "> SELECT make_time(6, 30, 45.887);\n06:30:45.887\n> SELECT make_time(NULL, 30, 0);\nNULL",
    "note" => ""
  },
  "make_timestamp_ltz" => %{
    "usage" => "make_timestamp_ltz(year, month, day, hour, min, sec[, timezone]) - Create the current timestamp with local time zone from year, month, day, hour, min, sec and (optional) timezone fields. If the configuration `spark.sql.ansi.enabled` is false, the function returns NULL on invalid inputs. Otherwise, it will throw an error instead.\nmake_timestamp_ltz(date, time[, timezone]) - Create a local date-time from date, time and (optional) timezone fields.",
    "examples" => "> SELECT make_timestamp_ltz(2014, 12, 28, 6, 30, 45.887);\n2014-12-28 06:30:45.887\n> SELECT make_timestamp_ltz(2014, 12, 28, 6, 30, 45.887, 'CET');\n2014-12-27 21:30:45.887\n> SELECT make_timestamp_ltz(2019, 6, 30, 23, 59, 60);\n2019-07-01 00:00:00\n> SELECT make_timestamp_ltz(null, 7, 22, 15, 30, 0);\nNULL\n> SELECT make_timestamp_ltz(DATE'2014-12-28', TIME'6:30:45.887');\n2014-12-28 06:30:45.887\n> SELECT make_timestamp_ltz(DATE'2014-12-28', TIME'6:30:45.887', 'CET');\n2014-12-27 21:30:45.887",
    "note" => ""
  },
  "make_valid_utf8" => %{
    "usage" => "make_valid_utf8(str) - Returns the original string if `str` is a valid UTF-8 string, otherwise returns a new string whose invalid UTF8 byte sequences are replaced using the UNICODE replacement character U+FFFD.",
    "examples" => "> SELECT make_valid_utf8('Spark');\nSpark\n> SELECT make_valid_utf8(x'61');\na\n> SELECT make_valid_utf8(x'80');\n�\n> SELECT make_valid_utf8(x'61C262');\na�b",
    "note" => ""
  },
  "make_ym_interval" => %{
    "usage" => "make_ym_interval([years[, months]]) - Make year-month interval from years, months.",
    "examples" => "> SELECT make_ym_interval(1, 2);\n1-2\n> SELECT make_ym_interval(1, 0);\n1-0\n> SELECT make_ym_interval(-1, 1);\n-0-11\n> SELECT make_ym_interval(2);\n2-0",
    "note" => ""
  },
  "map" => %{
    "usage" => "map(key0, value0, key1, value1, ...) - Creates a map with the given key/value pairs.",
    "examples" => "> SELECT map(1.0, '2', 3.0, '4');\n{1.0:\"2\",3.0:\"4\"}",
    "note" => ""
  },
  "map_concat" => %{
    "usage" => "map_concat(map, ...) - Returns the union of all the given maps",
    "examples" => "> SELECT map_concat(map(1, 'a', 2, 'b'), map(3, 'c'));\n{1:\"a\",2:\"b\",3:\"c\"}",
    "note" => ""
  },
  "map_contains_key" => %{
    "usage" => "map_contains_key(map, key) - Returns true if the map contains the key.",
    "examples" => "> SELECT map_contains_key(map(1, 'a', 2, 'b'), 1);\ntrue\n> SELECT map_contains_key(map(1, 'a', 2, 'b'), 3);\nfalse",
    "note" => ""
  },
  "map_entries" => %{
    "usage" => "map_entries(map) - Returns an unordered array of all entries in the given map.",
    "examples" => "> SELECT map_entries(map(1, 'a', 2, 'b'));\n[{\"key\":1,\"value\":\"a\"},{\"key\":2,\"value\":\"b\"}]",
    "note" => ""
  },
  "map_filter" => %{
    "usage" => "map_filter(expr, func) - Filters entries in a map using the function.",
    "examples" => "> SELECT map_filter(map(1, 0, 2, 2, 3, -1), (k, v) -> k > v);\n{1:0,3:-1}",
    "note" => ""
  },
  "map_from_arrays" => %{
    "usage" => "map_from_arrays(keys, values) - Creates a map with a pair of the given key/value arrays. All elements\nin keys should not be null",
    "examples" => "> SELECT map_from_arrays(array(1.0, 3.0), array('2', '4'));\n{1.0:\"2\",3.0:\"4\"}",
    "note" => ""
  },
  "map_from_entries" => %{
    "usage" => "map_from_entries(arrayOfEntries) - Returns a map created from the given array of entries.",
    "examples" => "> SELECT map_from_entries(array(struct(1, 'a'), struct(2, 'b')));\n{1:\"a\",2:\"b\"}",
    "note" => ""
  },
  "map_keys" => %{
    "usage" => "map_keys(map) - Returns an unordered array containing the keys of the map.",
    "examples" => "> SELECT map_keys(map(1, 'a', 2, 'b'));\n[1,2]",
    "note" => ""
  },
  "map_values" => %{
    "usage" => "map_values(map) - Returns an unordered array containing the values of the map.",
    "examples" => "> SELECT map_values(map(1, 'a', 2, 'b'));\n[\"a\",\"b\"]",
    "note" => ""
  },
  "map_zip_with" => %{
    "usage" => "map_zip_with(map1, map2, function) - Merges two given maps into a single map by applying\nfunction to the pair of values with the same key. For keys only presented in one map,\nNULL will be passed as the value for the missing key. If an input map contains duplicated\nkeys, only the first entry of the duplicated key is passed into the lambda function.",
    "examples" => "> SELECT map_zip_with(map(1, 'a', 2, 'b'), map(1, 'x', 2, 'y'), (k, v1, v2) -> concat(v1, v2));\n{1:\"ax\",2:\"by\"}\n> SELECT map_zip_with(map('a', 1, 'b', 2), map('b', 3, 'c', 4), (k, v1, v2) -> coalesce(v1, 0) + coalesce(v2, 0));\n{\"a\":1,\"b\":5,\"c\":4}",
    "note" => ""
  },
  "mask" => %{
    "usage" => "mask(input[, upperChar, lowerChar, digitChar, otherChar]) - masks the given string value.\nThe function replaces characters with 'X' or 'x', and numbers with 'n'.\nThis can be useful for creating copies of tables with sensitive information removed.",
    "examples" => "> SELECT mask('abcd-EFGH-8765-4321');\nxxxx-XXXX-nnnn-nnnn\n> SELECT mask('abcd-EFGH-8765-4321', 'Q');\nxxxx-QQQQ-nnnn-nnnn\n> SELECT mask('AbCD123-@$#', 'Q', 'q');\nQqQQnnn-@$#\n> SELECT mask('AbCD123-@$#');\nXxXXnnn-@$#\n> SELECT mask('AbCD123-@$#', 'Q');\nQxQQnnn-@$#\n> SELECT mask('AbCD123-@$#', 'Q', 'q');\nQqQQnnn-@$#\n> SELECT mask('AbCD123-@$#', 'Q', 'q', 'd');\nQqQQddd-@$#\n> SELECT mask('AbCD123-@$#', 'Q', 'q', 'd', 'o');\nQqQQdddoooo\n> SELECT mask('AbCD123-@$#', NULL, 'q', 'd', 'o');\nAqCDdddoooo\n> SELECT mask('AbCD123-@$#', NULL, NULL, 'd', 'o');\nAbCDdddoooo\n> SELECT mask('AbCD123-@$#', NULL, NULL, NULL, 'o');\nAbCD123oooo\n> SELECT mask(NULL, NULL, NULL, NULL, 'o');\nNULL\n> SELECT mask(NULL);\nNULL\n> SELECT mask('AbCD123-@$#', NULL, NULL, NULL, NULL);\nAbCD123-@$#",
    "note" => ""
  },
  "max" => %{
    "usage" => "max(expr) - Returns the maximum value of `expr`.",
    "examples" => "> SELECT max(col) FROM VALUES (10), (50), (20) AS tab(col);\n50",
    "note" => ""
  },
  "max_by" => %{
    "usage" => "max_by(x, y) - Returns the value of `x` associated with the maximum value of `y`.\nmax_by(x, y, k) - Returns an array of the `k` values of `x` associated with the\nmaximum values of `y`, sorted in descending order by `y`.\nReturns NULL if there are no non-NULL ordering values.",
    "examples" => "> SELECT max_by(x, y) FROM VALUES ('a', 10), ('b', 50), ('c', 20) AS tab(x, y);\nb\n> SELECT max_by(x, y, 2) FROM VALUES ('a', 10), ('b', 50), ('c', 20) AS tab(x, y);\n[\"b\",\"c\"]",
    "note" => "The function is non-deterministic so the output order can be different for\nthose associated the same values of `y`.\nThe maximum value of `k` is 100000."
  },
  "md5" => %{
    "usage" => "md5(expr) - Returns an MD5 128-bit checksum as a hex string of `expr`.",
    "examples" => "> SELECT md5('Spark');\n8cde774d6f7333752ed72cacddb05126",
    "note" => ""
  },
  "median" => %{
    "usage" => "median(col) - Returns the median of numeric or ANSI interval column `col`.",
    "examples" => "> SELECT median(col) FROM VALUES (0), (10) AS tab(col);\n5.0\n> SELECT median(col) FROM VALUES (INTERVAL '0' MONTH), (INTERVAL '10' MONTH) AS tab(col);\n0-5",
    "note" => ""
  },
  "min" => %{
    "usage" => "min(expr) - Returns the minimum value of `expr`.",
    "examples" => "> SELECT min(col) FROM VALUES (10), (-1), (20) AS tab(col);\n-1",
    "note" => ""
  },
  "min_by" => %{
    "usage" => "min_by(x, y) - Returns the value of `x` associated with the minimum value of `y`.\nmin_by(x, y, k) - Returns an array of the `k` values of `x` associated with the\nminimum values of `y`, sorted in ascending order by `y`.\nReturns NULL if there are no non-NULL ordering values.",
    "examples" => "> SELECT min_by(x, y) FROM VALUES ('a', 10), ('b', 50), ('c', 20) AS tab(x, y);\na\n> SELECT min_by(x, y, 2) FROM VALUES ('a', 10), ('b', 50), ('c', 20) AS tab(x, y);\n[\"a\",\"c\"]",
    "note" => "The function is non-deterministic so the output order can be different for\nthose associated the same values of `y`.\nThe maximum value of `k` is 100000."
  },
  "minute" => %{
    "usage" => "minute(expr) - Returns the minute component of the given expression.\nIf `expr` is a TIMESTAMP or a string that can be cast to timestamp,\nit returns the minute of that timestamp.\nIf `expr` is a TIME type (since 4.1.0), it returns the minute of the time-of-day.",
    "examples" => "> SELECT minute('2009-07-30 12:58:59');\n58\n> SELECT minute(TIME'23:59:59.999999');\n59",
    "note" => ""
  },
  "mode" => %{
    "usage" => "mode(col[, deterministic]) - Returns the most frequent value for the values within `col`. NULL values are ignored. If all the values are NULL, or there are 0 rows, returns NULL.\nWhen multiple values have the same greatest frequency then either any of values is returned if `deterministic` is false or is not defined, or the lowest value is returned if `deterministic` is true.\nmode() WITHIN GROUP (ORDER BY col) - Returns the most frequent value for the values within `col` (specified in ORDER BY clause). NULL values are ignored.\nIf all the values are NULL, or there are 0 rows, returns NULL. When multiple values have the same greatest frequency only one value will be returned.\nThe value will be chosen based on sort direction. Return the smallest value if sort direction is asc or the largest value if sort direction is desc from multiple values with the same frequency.",
    "examples" => "> SELECT mode(col) FROM VALUES (0), (10), (10) AS tab(col);\n10\n> SELECT mode(col) FROM VALUES (INTERVAL '0' MONTH), (INTERVAL '10' MONTH), (INTERVAL '10' MONTH) AS tab(col);\n0-10\n> SELECT mode(col) FROM VALUES (0), (10), (10), (null), (null), (null) AS tab(col);\n10\n> SELECT mode(col, false) FROM VALUES (-10), (0), (10) AS tab(col);\n0\n> SELECT mode(col, true) FROM VALUES (-10), (0), (10) AS tab(col);\n-10\n> SELECT mode() WITHIN GROUP (ORDER BY col) FROM VALUES (0), (10), (10) AS tab(col);\n10\n> SELECT mode() WITHIN GROUP (ORDER BY col) FROM VALUES (0), (10), (10), (20), (20) AS tab(col);\n10\n> SELECT mode() WITHIN GROUP (ORDER BY col DESC) FROM VALUES (0), (10), (10), (20), (20) AS tab(col);\n20",
    "note" => ""
  },
  "monotonically_increasing_id" => %{
    "usage" => "monotonically_increasing_id() - Returns monotonically increasing 64-bit integers. The generated ID is guaranteed\nto be monotonically increasing and unique, but not consecutive. The current implementation\nputs the partition ID in the upper 31 bits, and the lower 33 bits represent the record number\nwithin each partition. The assumption is that the data frame has less than 1 billion\npartitions, and each partition has less than 8 billion records.\nThe function is non-deterministic because its result depends on partition IDs.",
    "examples" => "> SELECT monotonically_increasing_id();\n0",
    "note" => ""
  },
  "month" => %{
    "usage" => "month(date) - Returns the month component of the date/timestamp.",
    "examples" => "> SELECT month('2016-07-30');\n7",
    "note" => ""
  },
  "monthname" => %{
    "usage" => "monthname(date) - Returns the three-letter abbreviated month name from the given date.",
    "examples" => "> SELECT monthname('2008-02-20');\nFeb",
    "note" => ""
  },
  "months_between" => %{
    "usage" => "months_between(timestamp1, timestamp2[, roundOff]) - If `timestamp1` is later than `timestamp2`, then the result\nis positive. If `timestamp1` and `timestamp2` are on the same day of month, or both\nare the last day of month, time of day will be ignored. Otherwise, the difference is\ncalculated based on 31 days per month, and rounded to 8 digits unless roundOff=false.",
    "examples" => "> SELECT months_between('1997-02-28 10:30:00', '1996-10-30');\n3.94959677\n> SELECT months_between('1997-02-28 10:30:00', '1996-10-30', false);\n3.9495967741935485",
    "note" => ""
  },
  "named_struct" => %{
    "usage" => "named_struct(name1, val1, name2, val2, ...) - Creates a struct with the given field names and values.",
    "examples" => "> SELECT named_struct(\"a\", 1, \"b\", 2, \"c\", 3);\n{\"a\":1,\"b\":2,\"c\":3}",
    "note" => ""
  },
  "nanvl" => %{
    "usage" => "nanvl(expr1, expr2) - Returns `expr1` if it's not NaN, or `expr2` otherwise.",
    "examples" => "> SELECT nanvl(cast('NaN' as double), 123);\n123.0",
    "note" => ""
  },
  "negative" => %{
    "usage" => "negative(expr) - Returns the negated value of `expr`.",
    "examples" => "> SELECT negative(1);\n-1",
    "note" => ""
  },
  "next_day" => %{
    "usage" => "next_day(start_date, day_of_week) - Returns the first date which is later than `start_date` and named as indicated.\nThe function returns NULL if at least one of the input parameters is NULL.\nWhen both of the input parameters are not NULL and day_of_week is an invalid input,\nthe function throws SparkIllegalArgumentException if `spark.sql.ansi.enabled` is set to true, otherwise NULL.",
    "examples" => "> SELECT next_day('2015-01-14', 'TU');\n2015-01-20",
    "note" => ""
  },
  "now" => %{
    "usage" => "now() - Returns the current timestamp at the start of query evaluation.",
    "examples" => "> SELECT now();\n2020-04-25 15:49:11.914",
    "note" => ""
  },
  "nth_value" => %{
    "usage" => "nth_value(input[, offset]) - Returns the value of `input` at the row that is the `offset`th row\nfrom beginning of the window frame. Offset starts at 1. If ignoreNulls=true, we will skip\nnulls when finding the `offset`th row. Otherwise, every row counts for the `offset`. If\nthere is no such an `offset`th row (e.g., when the offset is 10, size of the window frame\nis less than 10), null is returned.",
    "examples" => "> SELECT a, b, nth_value(b, 2) OVER (PARTITION BY a ORDER BY b) FROM VALUES ('A1', 2), ('A1', 1), ('A2', 3), ('A1', 1) tab(a, b);\nA1\t1\t1\nA1\t1\t1\nA1\t2\t1\nA2\t3\tNULL",
    "note" => ""
  },
  "ntile" => %{
    "usage" => "ntile(n) - Divides the rows for each window partition into `n` buckets ranging\nfrom 1 to at most `n`.",
    "examples" => "> SELECT a, b, ntile(2) OVER (PARTITION BY a ORDER BY b) FROM VALUES ('A1', 2), ('A1', 1), ('A2', 3), ('A1', 1) tab(a, b);\nA1\t1\t1\nA1\t1\t1\nA1\t2\t2\nA2\t3\t1",
    "note" => ""
  },
  "nullif" => %{
    "usage" => "nullif(expr1, expr2) - Returns null if `expr1` equals to `expr2`, or `expr1` otherwise.",
    "examples" => "> SELECT nullif(2, 2);\nNULL",
    "note" => ""
  },
  "nullifzero" => %{
    "usage" => "nullifzero(expr) - Returns null if `expr` is equal to zero, or `expr` otherwise.",
    "examples" => "> SELECT nullifzero(0);\nNULL\n> SELECT nullifzero(2);\n2",
    "note" => ""
  },
  "nvl" => %{
    "usage" => "nvl(expr1, expr2) - Returns `expr2` if `expr1` is null, or `expr1` otherwise.",
    "examples" => "> SELECT nvl(NULL, array('2'));\n[\"2\"]",
    "note" => ""
  },
  "nvl2" => %{
    "usage" => "nvl2(expr1, expr2, expr3) - Returns `expr2` if `expr1` is not null, or `expr3` otherwise.",
    "examples" => "> SELECT nvl2(NULL, 2, 1);\n1",
    "note" => ""
  },
  "octet_length" => %{
    "usage" => "octet_length(expr) - Returns the byte length of string data or number of bytes of binary data.",
    "examples" => "> SELECT octet_length('Spark SQL');\n9\n> SELECT octet_length(x'537061726b2053514c');\n9",
    "note" => ""
  },
  "overlay" => %{
    "usage" => "overlay(input, replace, pos[, len]) - Replace `input` with `replace` that starts at `pos` and is of length `len`.",
    "examples" => "> SELECT overlay('Spark SQL' PLACING '_' FROM 6);\nSpark_SQL\n> SELECT overlay('Spark SQL' PLACING 'CORE' FROM 7);\nSpark CORE\n> SELECT overlay('Spark SQL' PLACING 'ANSI ' FROM 7 FOR 0);\nSpark ANSI SQL\n> SELECT overlay('Spark SQL' PLACING 'tructured' FROM 2 FOR 4);\nStructured SQL\n> SELECT overlay(encode('Spark SQL', 'utf-8') PLACING encode('_', 'utf-8') FROM 6);\nSpark_SQL\n> SELECT overlay(encode('Spark SQL', 'utf-8') PLACING encode('CORE', 'utf-8') FROM 7);\nSpark CORE\n> SELECT overlay(encode('Spark SQL', 'utf-8') PLACING encode('ANSI ', 'utf-8') FROM 7 FOR 0);\nSpark ANSI SQL\n> SELECT overlay(encode('Spark SQL', 'utf-8') PLACING encode('tructured', 'utf-8') FROM 2 FOR 4);\nStructured SQL",
    "note" => ""
  },
  "parse_json" => %{
    "usage" => "parse_json(jsonStr) - Parse a JSON string as a Variant value. Throw an exception when the string is not valid JSON value.",
    "examples" => "> SELECT parse_json('{\"a\":1,\"b\":0.8}');\n{\"a\":1,\"b\":0.8}",
    "note" => ""
  },
  "parse_url" => %{
    "usage" => "parse_url(url, partToExtract[, key]) - Extracts a part from a URL.",
    "examples" => "> SELECT parse_url('http://spark.apache.org/path?query=1', 'HOST');\nspark.apache.org\n> SELECT parse_url('http://spark.apache.org/path?query=1', 'QUERY');\nquery=1\n> SELECT parse_url('http://spark.apache.org/path?query=1', 'QUERY', 'query');\n1",
    "note" => ""
  },
  "percent_rank" => %{
    "usage" => "percent_rank() - Computes the percentage ranking of a value in a group of values.",
    "examples" => "> SELECT a, b, percent_rank(b) OVER (PARTITION BY a ORDER BY b) FROM VALUES ('A1', 2), ('A1', 1), ('A2', 3), ('A1', 1) tab(a, b);\nA1\t1\t0.0\nA1\t1\t0.0\nA1\t2\t1.0\nA2\t3\t0.0",
    "note" => ""
  },
  "percentile" => %{
    "usage" => "percentile(col, percentage [, frequency]) - Returns the exact percentile value of numeric\nor ANSI interval column `col` at the given percentage. The value of percentage must be\nbetween 0.0 and 1.0. The value of frequency should be positive integral\npercentile(col, array(percentage1 [, percentage2]...) [, frequency]) - Returns the exact\npercentile value array of numeric column `col` at the given percentage(s). Each value\nof the percentage array must be between 0.0 and 1.0. The value of frequency should be\npositive integral",
    "examples" => "> SELECT percentile(col, 0.3) FROM VALUES (0), (10) AS tab(col);\n3.0\n> SELECT percentile(col, array(0.25, 0.75)) FROM VALUES (0), (10) AS tab(col);\n[2.5,7.5]\n> SELECT percentile(col, 0.5) FROM VALUES (INTERVAL '0' MONTH), (INTERVAL '10' MONTH) AS tab(col);\n0-5\n> SELECT percentile(col, array(0.2, 0.5)) FROM VALUES (INTERVAL '0' SECOND), (INTERVAL '10' SECOND) AS tab(col);\n[0 00:00:02.000000000,0 00:00:05.000000000]",
    "note" => ""
  },
  "percentile_approx" => %{
    "usage" => "percentile_approx(col, percentage [, accuracy]) - Returns the approximate `percentile` of the numeric or\nansi interval column `col` which is the smallest value in the ordered `col` values (sorted\nfrom least to greatest) such that no more than `percentage` of `col` values is less than\nthe value or equal to that value. The value of percentage must be between 0.0 and 1.0.\nThe `accuracy` parameter (default: 10000) is a positive numeric literal which controls\napproximation accuracy at the cost of memory. Higher value of `accuracy` yields better\naccuracy, `1.0/accuracy` is the relative error of the approximation.\nWhen `percentage` is an array, each value of the percentage array must be between 0.0 and 1.0.\nIn this case, returns the approximate percentile array of column `col` at the given\npercentage array.",
    "examples" => "> SELECT percentile_approx(col, array(0.5, 0.4, 0.1), 100) FROM VALUES (0), (1), (2), (10) AS tab(col);\n[1,1,0]\n> SELECT percentile_approx(col, 0.5, 100) FROM VALUES (0), (6), (7), (9), (10) AS tab(col);\n7\n> SELECT percentile_approx(col, 0.5, 100) FROM VALUES (INTERVAL '0' MONTH), (INTERVAL '1' MONTH), (INTERVAL '2' MONTH), (INTERVAL '10' MONTH) AS tab(col);\n0-1\n> SELECT percentile_approx(col, array(0.5, 0.7), 100) FROM VALUES (INTERVAL '0' SECOND), (INTERVAL '1' SECOND), (INTERVAL '2' SECOND), (INTERVAL '10' SECOND) AS tab(col);\n[0 00:00:01.000000000,0 00:00:02.000000000]",
    "note" => ""
  },
  "pi" => %{
    "usage" => "pi() - Returns pi.",
    "examples" => "> SELECT pi();\n3.141592653589793",
    "note" => ""
  },
  "pmod" => %{
    "usage" => "pmod(expr1, expr2) - Returns the positive value of `expr1` mod `expr2`.",
    "examples" => "> SELECT pmod(10, 3);\n1\n> SELECT pmod(-10, 3);\n2",
    "note" => ""
  },
  "posexplode" => %{
    "usage" => "posexplode(expr) - Separates the elements of array `expr` into multiple rows with positions, or the elements of map `expr` into multiple rows and columns with positions. Unless specified otherwise, uses the column name `pos` for position, `col` for elements of the array or `key` and `value` for elements of the map.",
    "examples" => "> SELECT posexplode(array(10,20));\n0\t10\n1\t20\n> SELECT posexplode(collection => array(10,20));\n0\t10\n1\t20",
    "note" => ""
  },
  "posexplode_outer" => %{
    "usage" => "posexplode_outer(expr) - Separates the elements of array `expr` into multiple rows with positions, or the elements of map `expr` into multiple rows and columns with positions. Unless specified otherwise, uses the column name `pos` for position, `col` for elements of the array or `key` and `value` for elements of the map.",
    "examples" => "> SELECT posexplode_outer(array(10,20));\n0\t10\n1\t20\n> SELECT posexplode_outer(collection => array(10,20));\n0\t10\n1\t20",
    "note" => ""
  },
  "position" => %{
    "usage" => "position(substr, str[, pos]) - Returns the position of the first occurrence of `substr` in `str` after position `pos`.\nThe given `pos` and return value are 1-based.",
    "examples" => "> SELECT position('bar', 'foobarbar');\n4\n> SELECT position('bar', 'foobarbar', 5);\n7\n> SELECT POSITION('bar' IN 'foobarbar');\n4",
    "note" => ""
  },
  "positive" => %{
    "usage" => "positive(expr) - Returns the value of `expr`.",
    "examples" => "> SELECT positive(1);\n1",
    "note" => ""
  },
  "power" => %{
    "usage" => "power(expr1, expr2) - Raises `expr1` to the power of `expr2`.",
    "examples" => "> SELECT power(2, 3);\n8.0",
    "note" => ""
  },
  "printf" => %{
    "usage" => "printf(strfmt, obj, ...) - Returns a formatted string from printf-style format strings.",
    "examples" => "> SELECT printf(\"Hello World %d %s\", 100, \"days\");\nHello World 100 days",
    "note" => ""
  },
  "quarter" => %{
    "usage" => "quarter(date) - Returns the quarter of the year for date, in the range 1 to 4.",
    "examples" => "> SELECT quarter('2016-08-31');\n3",
    "note" => ""
  },
  "quote" => %{
    "usage" => "quote(str) - Returns `str` enclosed by single quotes and each instance of single quote in it is preceded by a backslash.",
    "examples" => "> SELECT quote('Don\\'t');\n'Don\\'t'",
    "note" => ""
  },
  "radians" => %{
    "usage" => "radians(expr) - Converts degrees to radians.",
    "examples" => "> SELECT radians(180);\n3.141592653589793",
    "note" => ""
  },
  "raise_error" => %{
    "usage" => "raise_error( expr ) - Throws a USER_RAISED_EXCEPTION with `expr` as message.",
    "examples" => "> SELECT raise_error('custom error message');\n[USER_RAISED_EXCEPTION] custom error message",
    "note" => ""
  },
  "rand" => %{
    "usage" => "rand([seed]) - Returns a random value with independent and identically distributed (i.i.d.) uniformly distributed values in [0, 1).",
    "examples" => "> SELECT rand();\n0.9629742951434543\n> SELECT rand(0);\n0.7604953758285915\n> SELECT rand(null);\n0.7604953758285915",
    "note" => "The function is non-deterministic in general case."
  },
  "randn" => %{
    "usage" => "randn([seed]) - Returns a random value with independent and identically distributed (i.i.d.) values drawn from the standard normal distribution.",
    "examples" => "> SELECT randn();\n-0.3254147983080288\n> SELECT randn(0);\n1.6034991609278433\n> SELECT randn(null);\n1.6034991609278433",
    "note" => "The function is non-deterministic in general case."
  },
  "randstr" => %{
    "usage" => "randstr(length[, seed]) - Returns a string of the specified length whose characters are chosen\nuniformly at random from the following pool of characters: 0-9, a-z, A-Z. The random seed is\noptional. The string length must be a constant two-byte or four-byte integer (SMALLINT or INT,\nrespectively).",
    "examples" => "> SELECT randstr(3, 0) AS result;\nceV",
    "note" => ""
  },
  "rank" => %{
    "usage" => "rank() - Computes the rank of a value in a group of values. The result is one plus the number\nof rows preceding or equal to the current row in the ordering of the partition. The values\nwill produce gaps in the sequence.",
    "examples" => "> SELECT a, b, rank(b) OVER (PARTITION BY a ORDER BY b) FROM VALUES ('A1', 2), ('A1', 1), ('A2', 3), ('A1', 1) tab(a, b);\nA1\t1\t1\nA1\t1\t1\nA1\t2\t3\nA2\t3\t1",
    "note" => ""
  },
  "reduce" => %{
    "usage" => "reduce(expr, start, merge, finish) - Applies a binary operator to an initial state and all\nelements in the array, and reduces this to a single state. The final state is converted\ninto the final result by applying a finish function.",
    "examples" => "> SELECT reduce(array(1, 2, 3), 0, (acc, x) -> acc + x);\n6\n> SELECT reduce(array(1, 2, 3), 0, (acc, x) -> acc + x, acc -> acc * 10);\n60",
    "note" => ""
  },
  "reflect" => %{
    "usage" => "reflect(class, method[, arg1[, arg2 ..]]) - Calls a method with reflection.",
    "examples" => "> SELECT reflect('java.util.UUID', 'randomUUID');\nc33fb387-8500-4bfa-81d2-6e0e3e930df2\n> SELECT reflect('java.util.UUID', 'fromString', 'a5cf6c42-0c85-418f-af6c-3e4e5b1328f2');\na5cf6c42-0c85-418f-af6c-3e4e5b1328f2",
    "note" => ""
  },
  "regexp" => %{
    "usage" => "regexp(str, regexp) - Returns true if `str` matches `regexp`, or false otherwise.",
    "examples" => "> SET spark.sql.parser.escapedStringLiterals=true;\nspark.sql.parser.escapedStringLiterals\ttrue\n> SELECT regexp('%SystemDrive%\\Users\\John', '%SystemDrive%\\\\Users.*');\ntrue\n> SET spark.sql.parser.escapedStringLiterals=false;\nspark.sql.parser.escapedStringLiterals\tfalse\n> SELECT regexp('%SystemDrive%\\\\Users\\\\John', '%SystemDrive%\\\\\\\\Users.*');\ntrue\n> SELECT regexp('%SystemDrive%\\\\Users\\\\John', r'%SystemDrive%\\\\Users.*');\ntrue",
    "note" => "Use LIKE to match with simple string pattern."
  },
  "regexp_count" => %{
    "usage" => "regexp_count(str, regexp) - Returns a count of the number of times that the regular expression pattern `regexp` is matched in the string `str`.",
    "examples" => "> SELECT regexp_count('Steven Jones and Stephen Smith are the best players', 'Ste(v|ph)en');\n2\n> SELECT regexp_count('abcdefghijklmnopqrstuvwxyz', '[a-z]{3}');\n8",
    "note" => ""
  },
  "regexp_extract" => %{
    "usage" => "regexp_extract(str, regexp[, idx]) - Extract the first string in the `str` that match the `regexp`\nexpression and corresponding to the regex group index.",
    "examples" => "> SELECT regexp_extract('100-200', '(\\\\d+)-(\\\\d+)', 1);\n100\n> SELECT regexp_extract('100-200', r'(\\d+)-(\\d+)', 1);\n100",
    "note" => ""
  },
  "regexp_extract_all" => %{
    "usage" => "regexp_extract_all(str, regexp[, idx]) - Extract all strings in the `str` that match the `regexp`\nexpression and corresponding to the regex group index.",
    "examples" => "> SELECT regexp_extract_all('100-200, 300-400', '(\\\\d+)-(\\\\d+)', 1);\n[\"100\",\"300\"]\n> SELECT regexp_extract_all('100-200, 300-400', r'(\\d+)-(\\d+)', 1);\n[\"100\",\"300\"]",
    "note" => ""
  },
  "regexp_instr" => %{
    "usage" => "regexp_instr(str, regexp) - Searches a string for a regular expression and returns an integer that indicates the beginning position of the matched substring. Positions are 1-based, not 0-based. If no match is found, returns 0.",
    "examples" => "> SELECT regexp_instr(r\"\\abc\", r\"^\\\\abc$\");\n1\n> SELECT regexp_instr('user@spark.apache.org', '@[^.]*');\n5",
    "note" => ""
  },
  "regexp_like" => %{
    "usage" => "regexp_like(str, regexp) - Returns true if `str` matches `regexp`, or false otherwise.",
    "examples" => "> SET spark.sql.parser.escapedStringLiterals=true;\nspark.sql.parser.escapedStringLiterals\ttrue\n> SELECT regexp_like('%SystemDrive%\\Users\\John', '%SystemDrive%\\\\Users.*');\ntrue\n> SET spark.sql.parser.escapedStringLiterals=false;\nspark.sql.parser.escapedStringLiterals\tfalse\n> SELECT regexp_like('%SystemDrive%\\\\Users\\\\John', '%SystemDrive%\\\\\\\\Users.*');\ntrue\n> SELECT regexp_like('%SystemDrive%\\\\Users\\\\John', r'%SystemDrive%\\\\Users.*');\ntrue",
    "note" => "Use LIKE to match with simple string pattern."
  },
  "regexp_replace" => %{
    "usage" => "regexp_replace(str, regexp, rep[, position]) - Replaces all substrings of `str` that match `regexp` with `rep`.",
    "examples" => "> SELECT regexp_replace('100-200', '(\\\\d+)', 'num');\nnum-num\n> SELECT regexp_replace('100-200', r'(\\d+)', 'num');\nnum-num",
    "note" => ""
  },
  "regexp_substr" => %{
    "usage" => "regexp_substr(str, regexp) - Returns the substring that matches the regular expression `regexp` within the string `str`. If the regular expression is not found, the result is null.",
    "examples" => "> SELECT regexp_substr('Steven Jones and Stephen Smith are the best players', 'Ste(v|ph)en');\nSteven\n> SELECT regexp_substr('Steven Jones and Stephen Smith are the best players', 'Jeck');\nNULL",
    "note" => ""
  },
  "regr_avgx" => %{
    "usage" => "regr_avgx(y, x) - Returns the average of the independent variable for non-null pairs in a group, where `y` is the dependent variable and `x` is the independent variable.",
    "examples" => "> SELECT regr_avgx(y, x) FROM VALUES (1, 2), (2, 2), (2, 3), (2, 4) AS tab(y, x);\n2.75\n> SELECT regr_avgx(y, x) FROM VALUES (1, null) AS tab(y, x);\nNULL\n> SELECT regr_avgx(y, x) FROM VALUES (null, 1) AS tab(y, x);\nNULL\n> SELECT regr_avgx(y, x) FROM VALUES (1, 2), (2, null), (2, 3), (2, 4) AS tab(y, x);\n3.0\n> SELECT regr_avgx(y, x) FROM VALUES (1, 2), (2, null), (null, 3), (2, 4) AS tab(y, x);\n3.0",
    "note" => ""
  },
  "regr_avgy" => %{
    "usage" => "regr_avgy(y, x) - Returns the average of the dependent variable for non-null pairs in a group, where `y` is the dependent variable and `x` is the independent variable.",
    "examples" => "> SELECT regr_avgy(y, x) FROM VALUES (1, 2), (2, 2), (2, 3), (2, 4) AS tab(y, x);\n1.75\n> SELECT regr_avgy(y, x) FROM VALUES (1, null) AS tab(y, x);\nNULL\n> SELECT regr_avgy(y, x) FROM VALUES (null, 1) AS tab(y, x);\nNULL\n> SELECT regr_avgy(y, x) FROM VALUES (1, 2), (2, null), (2, 3), (2, 4) AS tab(y, x);\n1.6666666666666667\n> SELECT regr_avgy(y, x) FROM VALUES (1, 2), (2, null), (null, 3), (2, 4) AS tab(y, x);\n1.5",
    "note" => ""
  },
  "regr_count" => %{
    "usage" => "regr_count(y, x) - Returns the number of non-null number pairs in a group, where `y` is the dependent variable and `x` is the independent variable.",
    "examples" => "> SELECT regr_count(y, x) FROM VALUES (1, 2), (2, 2), (2, 3), (2, 4) AS tab(y, x);\n4\n> SELECT regr_count(y, x) FROM VALUES (1, null) AS tab(y, x);\n0\n> SELECT regr_count(y, x) FROM VALUES (null, 1) AS tab(y, x);\n0\n> SELECT regr_count(y, x) FROM VALUES (1, 2), (2, null), (2, 3), (2, 4) AS tab(y, x);\n3\n> SELECT regr_count(y, x) FROM VALUES (1, 2), (2, null), (null, 3), (2, 4) AS tab(y, x);\n2",
    "note" => ""
  },
  "regr_intercept" => %{
    "usage" => "regr_intercept(y, x) - Returns the intercept of the univariate linear regression line for non-null pairs in a group, where `y` is the dependent variable and `x` is the independent variable.",
    "examples" => "> SELECT regr_intercept(y, x) FROM VALUES (1, 1), (2, 2), (3, 3), (4, 4) AS tab(y, x);\n0.0\n> SELECT regr_intercept(y, x) FROM VALUES (1, null) AS tab(y, x);\nNULL\n> SELECT regr_intercept(y, x) FROM VALUES (null, 1) AS tab(y, x);\nNULL\n> SELECT regr_intercept(y, x) FROM VALUES (1, 1), (2, null), (3, 3), (4, 4) AS tab(y, x);\n0.0\n> SELECT regr_intercept(y, x) FROM VALUES (1, 1), (2, null), (null, 3), (4, 4) AS tab(y, x);\n0.0",
    "note" => ""
  },
  "regr_r2" => %{
    "usage" => "regr_r2(y, x) - Returns the coefficient of determination for non-null pairs in a group, where `y` is the dependent variable and `x` is the independent variable.",
    "examples" => "> SELECT regr_r2(y, x) FROM VALUES (1, 2), (2, 2), (2, 3), (2, 4) AS tab(y, x);\n0.2727272727272727\n> SELECT regr_r2(y, x) FROM VALUES (1, null) AS tab(y, x);\nNULL\n> SELECT regr_r2(y, x) FROM VALUES (null, 1) AS tab(y, x);\nNULL\n> SELECT regr_r2(y, x) FROM VALUES (1, 2), (2, null), (2, 3), (2, 4) AS tab(y, x);\n0.7500000000000001\n> SELECT regr_r2(y, x) FROM VALUES (1, 2), (2, null), (null, 3), (2, 4) AS tab(y, x);\n1.0",
    "note" => ""
  },
  "regr_slope" => %{
    "usage" => "regr_slope(y, x) - Returns the slope of the linear regression line for non-null pairs in a group, where `y` is the dependent variable and `x` is the independent variable.",
    "examples" => "> SELECT regr_slope(y, x) FROM VALUES (1, 1), (2, 2), (3, 3), (4, 4) AS tab(y, x);\n1.0\n> SELECT regr_slope(y, x) FROM VALUES (1, null) AS tab(y, x);\nNULL\n> SELECT regr_slope(y, x) FROM VALUES (null, 1) AS tab(y, x);\nNULL\n> SELECT regr_slope(y, x) FROM VALUES (1, 1), (2, null), (3, 3), (4, 4) AS tab(y, x);\n1.0\n> SELECT regr_slope(y, x) FROM VALUES (1, 1), (2, null), (null, 3), (4, 4) AS tab(y, x);\n1.0",
    "note" => ""
  },
  "regr_sxx" => %{
    "usage" => "regr_sxx(y, x) - Returns REGR_COUNT(y, x) * VAR_POP(x) for non-null pairs in a group, where `y` is the dependent variable and `x` is the independent variable.",
    "examples" => "> SELECT regr_sxx(y, x) FROM VALUES (1, 2), (2, 2), (2, 3), (2, 4) AS tab(y, x);\n2.75\n> SELECT regr_sxx(y, x) FROM VALUES (1, null) AS tab(y, x);\nNULL\n> SELECT regr_sxx(y, x) FROM VALUES (null, 1) AS tab(y, x);\nNULL\n> SELECT regr_sxx(y, x) FROM VALUES (1, 2), (2, null), (2, 3), (2, 4) AS tab(y, x);\n2.0\n> SELECT regr_sxx(y, x) FROM VALUES (1, 2), (2, null), (null, 3), (2, 4) AS tab(y, x);\n2.0",
    "note" => ""
  },
  "regr_sxy" => %{
    "usage" => "regr_sxy(y, x) - Returns REGR_COUNT(y, x) * COVAR_POP(y, x) for non-null pairs in a group, where `y` is the dependent variable and `x` is the independent variable.",
    "examples" => "> SELECT regr_sxy(y, x) FROM VALUES (1, 2), (2, 2), (2, 3), (2, 4) AS tab(y, x);\n0.75\n> SELECT regr_sxy(y, x) FROM VALUES (1, null) AS tab(y, x);\nNULL\n> SELECT regr_sxy(y, x) FROM VALUES (null, 1) AS tab(y, x);\nNULL\n> SELECT regr_sxy(y, x) FROM VALUES (1, 2), (2, null), (2, 3), (2, 4) AS tab(y, x);\n1.0\n> SELECT regr_sxy(y, x) FROM VALUES (1, 2), (2, null), (null, 3), (2, 4) AS tab(y, x);\n1.0",
    "note" => ""
  },
  "regr_syy" => %{
    "usage" => "regr_syy(y, x) - Returns REGR_COUNT(y, x) * VAR_POP(y) for non-null pairs in a group, where `y` is the dependent variable and `x` is the independent variable.",
    "examples" => "> SELECT regr_syy(y, x) FROM VALUES (1, 2), (2, 2), (2, 3), (2, 4) AS tab(y, x);\n0.75\n> SELECT regr_syy(y, x) FROM VALUES (1, null) AS tab(y, x);\nNULL\n> SELECT regr_syy(y, x) FROM VALUES (null, 1) AS tab(y, x);\nNULL\n> SELECT regr_syy(y, x) FROM VALUES (1, 2), (2, null), (2, 3), (2, 4) AS tab(y, x);\n0.6666666666666666\n> SELECT regr_syy(y, x) FROM VALUES (1, 2), (2, null), (null, 3), (2, 4) AS tab(y, x);\n0.5",
    "note" => ""
  },
  "repeat" => %{
    "usage" => "repeat(str, n) - Returns the string which repeats the given string value n times.",
    "examples" => "> SELECT repeat('123', 2);\n123123",
    "note" => ""
  },
  "replace" => %{
    "usage" => "replace(str, search[, replace]) - Replaces all occurrences of `search` with `replace`.",
    "examples" => "> SELECT replace('ABCabc', 'abc', 'DEF');\nABCDEF",
    "note" => ""
  },
  "reverse" => %{
    "usage" => "reverse(expr) - Returns a reversed string, a binary value with bytes in reverse order,\nor an array with reverse order of elements.",
    "examples" => "> SELECT reverse('Spark SQL');\nLQS krapS\n> SELECT reverse(array(2, 1, 4, 3));\n[3,4,1,2]\n> SELECT hex(reverse(x'CAFE'));\nFECA",
    "note" => "Reverse logic for arrays is available since 2.4.0.\nReverse logic for binary is available since 4.2.0."
  },
  "right" => %{
    "usage" => "right(str, len) - Returns the rightmost `len`(`len` can be string type) characters from the string `str`,if `len` is less or equal than 0 the result is an empty string.",
    "examples" => "> SELECT right('Spark SQL', 3);\nSQL",
    "note" => ""
  },
  "rint" => %{
    "usage" => "rint(expr) - Returns the double value that is closest in value to the argument and is equal to a mathematical integer.",
    "examples" => "> SELECT rint(12.3456);\n12.0",
    "note" => ""
  },
  "round" => %{
    "usage" => "round(expr, d) - Returns `expr` rounded to `d` decimal places using HALF_UP rounding mode.",
    "examples" => "> SELECT round(2.5, 0);\n3",
    "note" => ""
  },
  "row_number" => %{
    "usage" => "row_number() - Assigns a unique, sequential number to each row, starting with one,\naccording to the ordering of rows within the window partition.",
    "examples" => "> SELECT a, b, row_number() OVER (PARTITION BY a ORDER BY b) FROM VALUES ('A1', 2), ('A1', 1), ('A2', 3), ('A1', 1) tab(a, b);\nA1\t1\t1\nA1\t1\t2\nA1\t2\t3\nA2\t3\t1",
    "note" => ""
  },
  "rpad" => %{
    "usage" => "rpad(str, len[, pad]) - Returns `str`, right-padded with `pad` to a length of `len`.\nIf `str` is longer than `len`, the return value is shortened to `len` characters.\nIf `pad` is not specified, `str` will be padded to the right with space characters if it is\na character string, and with zeros if it is a binary string.",
    "examples" => "> SELECT rpad('hi', 5, '??');\nhi???\n> SELECT rpad('hi', 1, '??');\nh\n> SELECT rpad('hi', 5);\nhi\n> SELECT hex(rpad(unhex('aabb'), 5));\nAABB000000\n> SELECT hex(rpad(unhex('aabb'), 5, unhex('1122')));\nAABB112211",
    "note" => ""
  },
  "rtrim" => %{
    "usage" => "rtrim(str) - Removes the trailing space characters from `str`.",
    "examples" => "> SELECT rtrim('    SparkSQL   ');\nSparkSQL",
    "note" => ""
  },
  "schema_of_csv" => %{
    "usage" => "schema_of_csv(csv[, options]) - Returns schema in the DDL format of CSV string.",
    "examples" => "> SELECT schema_of_csv('1,abc');\nSTRUCT<_c0: INT, _c1: STRING>",
    "note" => ""
  },
  "schema_of_json" => %{
    "usage" => "schema_of_json(json[, options]) - Returns schema in the DDL format of JSON string.",
    "examples" => "> SELECT schema_of_json('[{\"col\":0}]');\nARRAY<STRUCT<col: BIGINT>>\n> SELECT schema_of_json('[{\"col\":01}]', map('allowNumericLeadingZeros', 'true'));\nARRAY<STRUCT<col: BIGINT>>",
    "note" => ""
  },
  "schema_of_variant" => %{
    "usage" => "schema_of_variant(v) - Returns schema in the SQL format of a variant.",
    "examples" => "> SELECT schema_of_variant(parse_json('null'));\nVOID\n> SELECT schema_of_variant(parse_json('[{\"b\":true,\"a\":0}]'));\nARRAY<OBJECT<a: BIGINT, b: BOOLEAN>>",
    "note" => ""
  },
  "schema_of_variant_agg" => %{
    "usage" => "schema_of_variant_agg(v) - Returns the merged schema in the SQL format of a variant column.",
    "examples" => "> SELECT schema_of_variant_agg(parse_json(j)) FROM VALUES ('1'), ('2'), ('3') AS tab(j);\nBIGINT\n> SELECT schema_of_variant_agg(parse_json(j)) FROM VALUES ('{\"a\": 1}'), ('{\"b\": true}'), ('{\"c\": 1.23}') AS tab(j);\nOBJECT<a: BIGINT, b: BOOLEAN, c: DECIMAL(3,2)>",
    "note" => ""
  },
  "schema_of_xml" => %{
    "usage" => "schema_of_xml(xml[, options]) - Returns schema in the DDL format of XML string.",
    "examples" => "> SELECT schema_of_xml('<p><a>1</a></p>');\nSTRUCT<a: BIGINT>\n> SELECT schema_of_xml('<p><a attr=\"2\">1</a><a>3</a></p>', map('excludeAttribute', 'true'));\nSTRUCT<a: ARRAY<BIGINT>>",
    "note" => ""
  },
  "sec" => %{
    "usage" => "sec(expr) - Returns the secant of `expr`, as if computed by `1/java.lang.Math.cos`.",
    "examples" => "> SELECT sec(0);\n1.0",
    "note" => ""
  },
  "second" => %{
    "usage" => "second(expr) - Returns the second component of the given expression.\nIf `expr` is a TIMESTAMP or a string that can be cast to timestamp,\nit returns the second of that timestamp.\nIf `expr` is a TIME type (since 4.1.0), it returns the second of the time-of-day.",
    "examples" => "> SELECT second('2018-02-14 12:58:59');\n59\n> SELECT second(TIME'13:25:59.999999');\n59",
    "note" => ""
  },
  "sentences" => %{
    "usage" => "sentences(str[, lang[, country]]) - Splits `str` into an array of array of words.",
    "examples" => "> SELECT sentences('Hi there! Good morning.');\n[[\"Hi\",\"there\"],[\"Good\",\"morning\"]]\n> SELECT sentences('Hi there! Good morning.', 'en');\n[[\"Hi\",\"there\"],[\"Good\",\"morning\"]]\n> SELECT sentences('Hi there! Good morning.', 'en', 'US');\n[[\"Hi\",\"there\"],[\"Good\",\"morning\"]]",
    "note" => ""
  },
  "sequence" => %{
    "usage" => "sequence(start, stop, step) - Generates an array of elements from start to stop (inclusive),\nincrementing by step. The type of the returned elements is the same as the type of argument\nexpressions.\nSupported types are: byte, short, integer, long, date, timestamp.\nThe start and stop expressions must resolve to the same type.\nIf start and stop expressions resolve to the 'date' or 'timestamp' type\nthen the step expression must resolve to the 'interval' or 'year-month interval' or\n'day-time interval' type, otherwise to the same type as the start and stop expressions.",
    "examples" => "> SELECT sequence(1, 5);\n[1,2,3,4,5]\n> SELECT sequence(5, 1);\n[5,4,3,2,1]\n> SELECT sequence(to_date('2018-01-01'), to_date('2018-03-01'), interval 1 month);\n[2018-01-01,2018-02-01,2018-03-01]\n> SELECT sequence(to_date('2018-01-01'), to_date('2018-03-01'), interval '0-1' year to month);\n[2018-01-01,2018-02-01,2018-03-01]",
    "note" => ""
  },
  "session_user" => %{
    "usage" => "session_user() - user name of current execution context.",
    "examples" => "> SELECT session_user();\nmockingjay",
    "note" => ""
  },
  "session_window" => %{
    "usage" => "session_window(time_column, gap_duration) - Generates session window given a timestamp specifying column and gap duration.\nSee <a href=\"https://spark.apache.org/docs/latest/structured-streaming-programming-guide.html#types-of-time-windows\">'Types of time windows'</a> in Structured Streaming guide doc for detailed explanation and examples.",
    "examples" => "> SELECT a, session_window.start, session_window.end, count(*) as cnt FROM VALUES ('A1', '2021-01-01 00:00:00'), ('A1', '2021-01-01 00:04:30'), ('A1', '2021-01-01 00:10:00'), ('A2', '2021-01-01 00:01:00') AS tab(a, b) GROUP by a, session_window(b, '5 minutes') ORDER BY a, start;\nA1\t2021-01-01 00:00:00\t2021-01-01 00:09:30\t2\nA1\t2021-01-01 00:10:00\t2021-01-01 00:15:00\t1\nA2\t2021-01-01 00:01:00\t2021-01-01 00:06:00\t1\n> SELECT a, session_window.start, session_window.end, count(*) as cnt FROM VALUES ('A1', '2021-01-01 00:00:00'), ('A1', '2021-01-01 00:04:30'), ('A1', '2021-01-01 00:10:00'), ('A2', '2021-01-01 00:01:00'), ('A2', '2021-01-01 00:04:30') AS tab(a, b) GROUP by a, session_window(b, CASE WHEN a = 'A1' THEN '5 minutes' WHEN a = 'A2' THEN '1 minute' ELSE '10 minutes' END) ORDER BY a, start;\nA1\t2021-01-01 00:00:00\t2021-01-01 00:09:30\t2\nA1\t2021-01-01 00:10:00\t2021-01-01 00:15:00\t1\nA2\t2021-01-01 00:01:00\t2021-01-01 00:02:00\t1\nA2\t2021-01-01 00:04:30\t2021-01-01 00:05:30\t1",
    "note" => ""
  },
  "sha" => %{
    "usage" => "sha(expr) - Returns a sha1 hash value as a hex string of the `expr`.",
    "examples" => "> SELECT sha('Spark');\n85f5955f4b27a9a4c2aab6ffe5d7189fc298b92c",
    "note" => ""
  },
  "sha1" => %{
    "usage" => "sha1(expr) - Returns a sha1 hash value as a hex string of the `expr`.",
    "examples" => "> SELECT sha1('Spark');\n85f5955f4b27a9a4c2aab6ffe5d7189fc298b92c",
    "note" => ""
  },
  "sha2" => %{
    "usage" => "sha2(expr, bitLength) - Returns a checksum of SHA-2 family as a hex string of `expr`.\nSHA-224, SHA-256, SHA-384, and SHA-512 are supported. Bit length of 0 is equivalent to 256.",
    "examples" => "> SELECT sha2('Spark', 256);\n529bc3b07127ecb7e53a4dcf1991d9152c24537d919178022b2c42657f79a26b",
    "note" => ""
  },
  "shiftleft" => %{
    "usage" => "base shiftleft exp - Bitwise left shift.",
    "examples" => "> SELECT shiftleft(2, 1);\n4\n> SELECT 2 << 1;\n4",
    "note" => "`<<` operator is added in Spark 4.0.0 as an alias for `shiftleft`."
  },
  "shiftright" => %{
    "usage" => "base shiftright expr - Bitwise (signed) right shift.",
    "examples" => "> SELECT shiftright(4, 1);\n2\n> SELECT 4 >> 1;\n2",
    "note" => "`>>` operator is added in Spark 4.0.0 as an alias for `shiftright`."
  },
  "shiftrightunsigned" => %{
    "usage" => "base shiftrightunsigned expr - Bitwise unsigned right shift.",
    "examples" => "> SELECT shiftrightunsigned(4, 1);\n2\n> SELECT 4 >>> 1;\n2",
    "note" => "`>>>` operator is added in Spark 4.0.0 as an alias for `shiftrightunsigned`."
  },
  "shuffle" => %{
    "usage" => "shuffle(array) - Returns a random permutation of the given array.",
    "examples" => "> SELECT shuffle(array(1, 20, 3, 5));\n[3,1,5,20]\n> SELECT shuffle(array(1, 20, null, 3));\n[20,null,3,1]",
    "note" => "The function is non-deterministic."
  },
  "sign" => %{
    "usage" => "sign(expr) - Returns -1.0, 0.0 or 1.0 as `expr` is negative, 0 or positive.",
    "examples" => "> SELECT sign(40);\n1.0\n> SELECT sign(INTERVAL -'100' YEAR);\n-1.0",
    "note" => ""
  },
  "signum" => %{
    "usage" => "signum(expr) - Returns -1.0, 0.0 or 1.0 as `expr` is negative, 0 or positive.",
    "examples" => "> SELECT signum(40);\n1.0\n> SELECT signum(INTERVAL -'100' YEAR);\n-1.0",
    "note" => ""
  },
  "sin" => %{
    "usage" => "sin(expr) - Returns the sine of `expr`, as if computed by `java.lang.Math.sin`.",
    "examples" => "> SELECT sin(0);\n0.0",
    "note" => ""
  },
  "sinh" => %{
    "usage" => "sinh(expr) - Returns hyperbolic sine of `expr`, as if computed by `java.lang.Math.sinh`.",
    "examples" => "> SELECT sinh(0);\n0.0",
    "note" => ""
  },
  "size" => %{
    "usage" => "size(expr) - Returns the size of an array or a map.\nThis function returns -1 for null input only if spark.sql.ansi.enabled is false and\nspark.sql.legacy.sizeOfNull is true. Otherwise, it returns null for null input.\nWith the default settings, the function returns null for null input.",
    "examples" => "> SELECT size(array('b', 'd', 'c', 'a'));\n4\n> SELECT size(map('a', 1, 'b', 2));\n2",
    "note" => ""
  },
  "skewness" => %{
    "usage" => "skewness(expr) - Returns the skewness value calculated from values of a group.",
    "examples" => "> SELECT skewness(col) FROM VALUES (-10), (-20), (100), (1000) AS tab(col);\n1.1135657469022011\n> SELECT skewness(col) FROM VALUES (-1000), (-100), (10), (20) AS tab(col);\n-1.1135657469022011",
    "note" => ""
  },
  "slice" => %{
    "usage" => "slice(x, start, length) - Subsets array x starting from index start (array indices start at 1, or starting from the end if start is negative) with the specified length.",
    "examples" => "> SELECT slice(array(1, 2, 3, 4), 2, 2);\n[2,3]\n> SELECT slice(array(1, 2, 3, 4), -2, 2);\n[3,4]",
    "note" => ""
  },
  "some" => %{
    "usage" => "some(expr) - Returns true if at least one value of `expr` is true.",
    "examples" => "> SELECT some(col) FROM VALUES (true), (false), (false) AS tab(col);\ntrue\n> SELECT some(col) FROM VALUES (NULL), (true), (false) AS tab(col);\ntrue\n> SELECT some(col) FROM VALUES (false), (false), (NULL) AS tab(col);\nfalse",
    "note" => ""
  },
  "sort_array" => %{
    "usage" => "sort_array(array[, ascendingOrder]) - Sorts the input array in ascending or descending order\naccording to the natural ordering of the array elements. NaN is greater than any non-NaN\nelements for double/float type. Null elements will be placed at the beginning of the returned\narray in ascending order or at the end of the returned array in descending order.",
    "examples" => "> SELECT sort_array(array('b', 'd', null, 'c', 'a'), true);\n[null,\"a\",\"b\",\"c\",\"d\"]\n> SELECT sort_array(array('b', 'd', null, 'c', 'a'), false);\n[\"d\",\"c\",\"b\",\"a\",null]",
    "note" => ""
  },
  "soundex" => %{
    "usage" => "soundex(str) - Returns Soundex code of the string.",
    "examples" => "> SELECT soundex('Miller');\nM460",
    "note" => ""
  },
  "spark_partition_id" => %{
    "usage" => "spark_partition_id() - Returns the current partition id.",
    "examples" => "> SELECT spark_partition_id();\n0",
    "note" => ""
  },
  "split" => %{
    "usage" => "split(str, regex, limit) - Splits `str` around occurrences that match `regex` and returns an array with a length of at most `limit`",
    "examples" => "> SELECT split('oneAtwoBthreeC', '[ABC]');\n[\"one\",\"two\",\"three\",\"\"]\n> SELECT split('oneAtwoBthreeC', '[ABC]', -1);\n[\"one\",\"two\",\"three\",\"\"]\n> SELECT split('oneAtwoBthreeC', '[ABC]', 2);\n[\"one\",\"twoBthreeC\"]",
    "note" => ""
  },
  "split_part" => %{
    "usage" => "split_part(str, delimiter, partNum) - Splits `str` by delimiter and return\nrequested part of the split (1-based). If any input is null, returns null.\nif `partNum` is out of range of split parts, returns empty string. If `partNum` is 0,\nthrows an error. If `partNum` is negative, the parts are counted backward from the\nend of the string. If the `delimiter` is an empty string, the `str` is not split.",
    "examples" => "> SELECT split_part('11.12.13', '.', 3);\n13",
    "note" => ""
  },
  "sqrt" => %{
    "usage" => "sqrt(expr) - Returns the square root of `expr`.",
    "examples" => "> SELECT sqrt(4);\n2.0",
    "note" => ""
  },
  "st_asbinary" => %{
    "usage" => "st_asbinary(geo[, endianness]) - Returns the geospatial value (value of type GEOGRAPHY or GEOMETRY) in WKB format using the specified endianness ('NDR' for little-endian, 'XDR' for big-endian), if provided. Defaults to little-endian encoding.",
    "examples" => "> SELECT hex(st_asbinary(st_geogfromwkb(X'0101000000000000000000F03F0000000000000040')));\n0101000000000000000000F03F0000000000000040\n> SELECT hex(st_asbinary(st_geomfromwkb(X'0101000000000000000000F03F0000000000000040'), 'XDR'));\n00000000013FF00000000000004000000000000000",
    "note" => ""
  },
  "st_geogfromwkb" => %{
    "usage" => "st_geogfromwkb(wkb) - Parses the WKB description of a geography and returns the corresponding GEOGRAPHY value.",
    "examples" => "> SELECT hex(st_asbinary(st_geogfromwkb(X'0101000000000000000000F03F0000000000000040')));\n0101000000000000000000F03F0000000000000040",
    "note" => ""
  },
  "st_geomfromwkb" => %{
    "usage" => "st_geomfromwkb(wkb[, srid]) - Parses the WKB description of a geometry and returns the corresponding GEOMETRY value.",
    "examples" => "> SELECT hex(st_asbinary(st_geomfromwkb(X'0101000000000000000000F03F0000000000000040')));\n0101000000000000000000F03F0000000000000040\n> SELECT st_srid(st_geomfromwkb(X'0101000000000000000000F03F0000000000000040'));\n0\n> SELECT hex(st_asbinary(st_geomfromwkb(X'0101000000000000000000F03F0000000000000040', 4326)));\n0101000000000000000000F03F0000000000000040\n> SELECT st_srid(st_geomfromwkb(X'0101000000000000000000F03F0000000000000040', 4326));\n4326",
    "note" => ""
  },
  "st_setsrid" => %{
    "usage" => "st_setsrid(geo, srid) - Returns a new GEOGRAPHY or GEOMETRY value whose SRID is the specified SRID value.",
    "examples" => "> SELECT st_srid(st_setsrid(ST_GeogFromWKB(X'0101000000000000000000F03F0000000000000040'), 4326));\n4326\n> SELECT st_srid(st_setsrid(ST_GeomFromWKB(X'0101000000000000000000F03F0000000000000040'), 3857));\n3857",
    "note" => ""
  },
  "st_srid" => %{
    "usage" => "st_srid(geo) - Returns the SRID of the input GEOGRAPHY or GEOMETRY value.",
    "examples" => "> SELECT st_srid(st_geogfromwkb(X'0101000000000000000000F03F0000000000000040'));\n4326\n> SELECT st_srid(st_geomfromwkb(X'0101000000000000000000F03F0000000000000040'));\n0\n> SELECT st_srid(NULL);\nNULL",
    "note" => ""
  },
  "stack" => %{
    "usage" => "stack(n, expr1, ..., exprk) - Separates `expr1`, ..., `exprk` into `n` rows. Uses column names col0, col1, etc. by default unless specified otherwise.",
    "examples" => "> SELECT stack(2, 1, 2, 3);\n1\t2\n3\tNULL",
    "note" => ""
  },
  "std" => %{
    "usage" => "std(expr) - Returns the sample standard deviation calculated from values of a group.",
    "examples" => "> SELECT std(col) FROM VALUES (1), (2), (3) AS tab(col);\n1.0",
    "note" => ""
  },
  "stddev" => %{
    "usage" => "stddev(expr) - Returns the sample standard deviation calculated from values of a group.",
    "examples" => "> SELECT stddev(col) FROM VALUES (1), (2), (3) AS tab(col);\n1.0",
    "note" => ""
  },
  "stddev_pop" => %{
    "usage" => "stddev_pop(expr) - Returns the population standard deviation calculated from values of a group.",
    "examples" => "> SELECT stddev_pop(col) FROM VALUES (1), (2), (3) AS tab(col);\n0.816496580927726",
    "note" => ""
  },
  "stddev_samp" => %{
    "usage" => "stddev_samp(expr) - Returns the sample standard deviation calculated from values of a group.",
    "examples" => "> SELECT stddev_samp(col) FROM VALUES (1), (2), (3) AS tab(col);\n1.0",
    "note" => ""
  },
  "str_to_map" => %{
    "usage" => "str_to_map(text[, pairDelim[, keyValueDelim]]) - Creates a map after splitting the text into key/value pairs using delimiters. Default delimiters are ',' for `pairDelim` and ':' for `keyValueDelim`. Both `pairDelim` and `keyValueDelim` are treated as regular expressions.",
    "examples" => "> SELECT str_to_map('a:1,b:2,c:3', ',', ':');\n{\"a\":\"1\",\"b\":\"2\",\"c\":\"3\"}\n> SELECT str_to_map('a');\n{\"a\":null}",
    "note" => ""
  },
  "string_agg" => %{
    "usage" => "string_agg(expr[, delimiter])[ WITHIN GROUP (ORDER BY key [ASC | DESC] [,...])] - Returns\nthe concatenation of non-NULL input values, separated by the delimiter ordered by key.\nIf all values are NULL, NULL is returned.",
    "examples" => "> SELECT string_agg(col) FROM VALUES ('a'), ('b'), ('c') AS tab(col);\nabc\n> SELECT string_agg(col) WITHIN GROUP (ORDER BY col DESC) FROM VALUES ('a'), ('b'), ('c') AS tab(col);\ncba\n> SELECT string_agg(col) FROM VALUES ('a'), (NULL), ('b') AS tab(col);\nab\n> SELECT string_agg(col) FROM VALUES ('a'), ('a') AS tab(col);\naa\n> SELECT string_agg(DISTINCT col) FROM VALUES ('a'), ('a'), ('b') AS tab(col);\nab\n> SELECT string_agg(col, ', ') FROM VALUES ('a'), ('b'), ('c') AS tab(col);\na, b, c\n> SELECT string_agg(col) FROM VALUES (NULL), (NULL) AS tab(col);\nNULL",
    "note" => "* If the order is not specified, the function is non-deterministic because\nthe order of the rows may be non-deterministic after a shuffle.\n* If DISTINCT is specified, then expr and key must be the same expression."
  },
  "struct" => %{
    "usage" => "struct(col1, col2, col3, ...) - Creates a struct with the given field values.",
    "examples" => "> SELECT struct(1, 2, 3);\n{\"col1\":1,\"col2\":2,\"col3\":3}",
    "note" => ""
  },
  "substr" => %{
    "usage" => "substr(str, pos[, len]) - Returns the substring of `str` that starts at `pos` and is of length `len`, or the slice of byte array that starts at `pos` and is of length `len`.\nsubstr(str FROM pos[ FOR len]]) - Returns the substring of `str` that starts at `pos` and is of length `len`, or the slice of byte array that starts at `pos` and is of length `len`.",
    "examples" => "> SELECT substr('Spark SQL', 5);\nk SQL\n> SELECT substr('Spark SQL', -3);\nSQL\n> SELECT substr('Spark SQL', 5, 1);\nk\n> SELECT substr('Spark SQL' FROM 5);\nk SQL\n> SELECT substr('Spark SQL' FROM -3);\nSQL\n> SELECT substr('Spark SQL' FROM 5 FOR 1);\nk\n> SELECT substr(encode('Spark SQL', 'utf-8'), 5);\nk SQL",
    "note" => ""
  },
  "substring" => %{
    "usage" => "substring(str, pos[, len]) - Returns the substring of `str` that starts at `pos` and is of length `len`, or the slice of byte array that starts at `pos` and is of length `len`.\nsubstring(str FROM pos[ FOR len]]) - Returns the substring of `str` that starts at `pos` and is of length `len`, or the slice of byte array that starts at `pos` and is of length `len`.",
    "examples" => "> SELECT substring('Spark SQL', 5);\nk SQL\n> SELECT substring('Spark SQL', -3);\nSQL\n> SELECT substring('Spark SQL', 5, 1);\nk\n> SELECT substring('Spark SQL' FROM 5);\nk SQL\n> SELECT substring('Spark SQL' FROM -3);\nSQL\n> SELECT substring('Spark SQL' FROM 5 FOR 1);\nk\n> SELECT substring(encode('Spark SQL', 'utf-8'), 5);\nk SQL",
    "note" => ""
  },
  "substring_index" => %{
    "usage" => "substring_index(str, delim, count) - Returns the substring from `str` before `count` occurrences of the delimiter `delim`.\nIf `count` is positive, everything to the left of the final delimiter (counting from the\nleft) is returned. If `count` is negative, everything to the right of the final delimiter\n(counting from the right) is returned. The function substring_index performs a case-sensitive match\nwhen searching for `delim`.",
    "examples" => "> SELECT substring_index('www.apache.org', '.', 2);\nwww.apache",
    "note" => ""
  },
  "sum" => %{
    "usage" => "sum(expr) - Returns the sum calculated from values of a group.",
    "examples" => "> SELECT sum(col) FROM VALUES (5), (10), (15) AS tab(col);\n30\n> SELECT sum(col) FROM VALUES (NULL), (10), (15) AS tab(col);\n25\n> SELECT sum(col) FROM VALUES (NULL), (NULL) AS tab(col);\nNULL",
    "note" => ""
  },
  "tan" => %{
    "usage" => "tan(expr) - Returns the tangent of `expr`, as if computed by `java.lang.Math.tan`.",
    "examples" => "> SELECT tan(0);\n0.0",
    "note" => ""
  },
  "tanh" => %{
    "usage" => "tanh(expr) - Returns the hyperbolic tangent of `expr`, as if computed by\n`java.lang.Math.tanh`.",
    "examples" => "> SELECT tanh(0);\n0.0",
    "note" => ""
  },
  "time_bucket" => %{
    "usage" => "time_bucket(bucketSize, ts[, origin]) - Returns the start of the bucket that `ts` falls into,\nwhere buckets are defined by the given `bucketSize` interval aligned to optional `origin`.\nFor `TIMESTAMP_NTZ`, bucketing is performed in UTC. For `TIMESTAMP`, year-month\ninterval buckets and calendar-day components of day-time interval buckets align\nto the session time zone.",
    "examples" => "> SELECT time_bucket(INTERVAL '15' MINUTE, TIMESTAMP '2024-01-01 11:27:00', TIMESTAMP '1970-01-01 00:00:00');\n2024-01-01 11:15:00\n> SELECT time_bucket(INTERVAL '1' HOUR, TIMESTAMP '2024-01-01 11:27:00');\n2024-01-01 11:00:00\n> SELECT time_bucket(INTERVAL '1' MONTH, TIMESTAMP '2024-07-20 14:30:00', TIMESTAMP '2024-06-15 09:00:00');\n2024-07-15 09:00:00",
    "note" => ""
  },
  "time_diff" => %{
    "usage" => "time_diff(unit, start, end) - Gets the difference between the times in the specified units.",
    "examples" => "> SELECT time_diff('HOUR', TIME'20:30:29', TIME'21:30:28');\n0\n> SELECT time_diff('HOUR', TIME'20:30:29', TIME'21:30:29');\n1\n> SELECT time_diff('HOUR', TIME'20:30:29', TIME'12:00:00');\n-8",
    "note" => ""
  },
  "time_from_micros" => %{
    "usage" => "time_from_micros(micros) - Creates a TIME value from microseconds since midnight.",
    "examples" => "> SELECT time_from_micros(0);\n00:00:00\n> SELECT time_from_micros(52200000000);\n14:30:00\n> SELECT time_from_micros(52200500000);\n14:30:00.5\n> SELECT time_from_micros(86399999999);\n23:59:59.999999",
    "note" => ""
  },
  "time_from_millis" => %{
    "usage" => "time_from_millis(millis) - Creates a TIME value from milliseconds since midnight.",
    "examples" => "> SELECT time_from_millis(0);\n00:00:00\n> SELECT time_from_millis(52200000);\n14:30:00\n> SELECT time_from_millis(52200500);\n14:30:00.5\n> SELECT time_from_millis(86399999);\n23:59:59.999",
    "note" => ""
  },
  "time_from_seconds" => %{
    "usage" => "time_from_seconds(seconds) - Creates a TIME value from seconds since midnight.",
    "examples" => "> SELECT time_from_seconds(0);\n00:00:00\n> SELECT time_from_seconds(52200);\n14:30:00\n> SELECT time_from_seconds(52200.5);\n14:30:00.5\n> SELECT time_from_seconds(86399.999999);\n23:59:59.999999",
    "note" => ""
  },
  "time_to_micros" => %{
    "usage" => "time_to_micros(time) - Returns the number of microseconds since midnight for the given TIME value.",
    "examples" => "> SELECT time_to_micros(TIME'00:00:00');\n0\n> SELECT time_to_micros(TIME'14:30:00');\n52200000000\n> SELECT time_to_micros(TIME'14:30:00.5');\n52200500000\n> SELECT time_to_micros(TIME'23:59:59.999999');\n86399999999",
    "note" => ""
  },
  "time_to_millis" => %{
    "usage" => "time_to_millis(time) - Returns the number of milliseconds since midnight for the given TIME value.",
    "examples" => "> SELECT time_to_millis(TIME'00:00:00');\n0\n> SELECT time_to_millis(TIME'14:30:00');\n52200000\n> SELECT time_to_millis(TIME'14:30:00.5');\n52200500\n> SELECT time_to_millis(TIME'23:59:59.999');\n86399999",
    "note" => ""
  },
  "time_to_seconds" => %{
    "usage" => "time_to_seconds(time) - Returns the number of seconds since midnight for the given TIME value.",
    "examples" => "> SELECT time_to_seconds(TIME'00:00:00');\n0.000000\n> SELECT time_to_seconds(TIME'14:30:00');\n52200.000000\n> SELECT time_to_seconds(TIME'14:30:00.5');\n52200.500000\n> SELECT time_to_seconds(TIME'23:59:59.999999');\n86399.999999",
    "note" => ""
  },
  "time_trunc" => %{
    "usage" => "time_trunc(unit, time) - Returns `time` truncated to the `unit`.",
    "examples" => "> SELECT time_trunc('HOUR', TIME'09:32:05.359');\n09:00:00\n> SELECT time_trunc('MILLISECOND', TIME'09:32:05.123456');\n09:32:05.123",
    "note" => ""
  },
  "timestamp_micros" => %{
    "usage" => "timestamp_micros(microseconds) - Creates timestamp from the number of microseconds since UTC epoch.",
    "examples" => "> SELECT timestamp_micros(1230219000123123);\n2008-12-25 07:30:00.123123",
    "note" => ""
  },
  "timestamp_millis" => %{
    "usage" => "timestamp_millis(milliseconds) - Creates timestamp from the number of milliseconds since UTC epoch.",
    "examples" => "> SELECT timestamp_millis(1230219000123);\n2008-12-25 07:30:00.123",
    "note" => ""
  },
  "timestamp_seconds" => %{
    "usage" => "timestamp_seconds(seconds) - Creates timestamp from the number of seconds (can be fractional) since UTC epoch.",
    "examples" => "> SELECT timestamp_seconds(1230219000);\n2008-12-25 07:30:00\n> SELECT timestamp_seconds(1230219000.123);\n2008-12-25 07:30:00.123",
    "note" => ""
  },
  "to_binary" => %{
    "usage" => "to_binary(str[, fmt]) - Converts the input `str` to a binary value based on the supplied `fmt`.\n`fmt` can be a case-insensitive string literal of \"hex\", \"utf-8\", \"utf8\", or \"base64\".\nBy default, the binary format for conversion is \"hex\" if `fmt` is omitted.\nThe function returns NULL if at least one of the input parameters is NULL.",
    "examples" => "> SELECT to_binary('abc', 'utf-8');\nabc",
    "note" => ""
  },
  "to_char" => %{
    "usage" => "to_char(expr, format) - Convert `expr` to a string based on the `format`.\nThrows an exception if the conversion fails. The format can consist of the following\ncharacters, case insensitive:\n'0' or '9': Specifies an expected digit between 0 and 9. A sequence of 0 or 9 in the format\nstring matches a sequence of digits in the input value, generating a result string of the\nsame length as the corresponding sequence in the format string. The result string is\nleft-padded with zeros if the 0/9 sequence comprises more digits than the matching part of\nthe decimal value, starts with 0, and is before the decimal point. Otherwise, it is\npadded with spaces.\n'.' or 'D': Specifies the position of the decimal point (optional, only allowed once).\n',' or 'G': Specifies the position of the grouping (thousands) separator (,). There must be\na 0 or 9 to the left and right of each grouping separator.\n'$': Specifies the location of the $ currency sign. This character may only be specified\nonce.\n'S' or 'MI': Specifies the position of a '-' or '+' sign (optional, only allowed once at\nthe beginning or end of the format string). Note that 'S' prints '+' for positive values\nbut 'MI' prints a space.\n'PR': Only allowed at the end of the format string; specifies that the result string will be\nwrapped by angle brackets if the input value is negative.\n('<1>').\nIf `expr` is a datetime, `format` shall be a valid datetime pattern, see <a href=\"https://spark.apache.org/docs/latest/sql-ref-datetime-pattern.html\">Datetime Patterns</a>.\nIf `expr` is a binary, it is converted to a string in one of the formats:\n'base64': a base 64 string.\n'hex': a string in the hexadecimal format.\n'utf-8': the input binary is decoded to UTF-8 string.",
    "examples" => "> SELECT to_char(454, '999');\n454\n> SELECT to_char(454.00, '000D00');\n454.00\n> SELECT to_char(12454, '99G999');\n12,454\n> SELECT to_char(78.12, '$99.99');\n$78.12\n> SELECT to_char(-12454.8, '99G999D9S');\n12,454.8-\n> SELECT to_char(date'2016-04-08', 'y');\n2016\n> SELECT to_char(x'537061726b2053514c', 'base64');\nU3BhcmsgU1FM\n> SELECT to_char(x'537061726b2053514c', 'hex');\n537061726B2053514C\n> SELECT to_char(encode('abc', 'utf-8'), 'utf-8');\nabc",
    "note" => ""
  },
  "to_csv" => %{
    "usage" => "to_csv(expr[, options]) - Returns a CSV string with a given struct value",
    "examples" => "> SELECT to_csv(named_struct('a', 1, 'b', 2));\n1,2\n> SELECT to_csv(named_struct('time', to_timestamp('2015-08-26', 'yyyy-MM-dd')), map('timestampFormat', 'dd/MM/yyyy'));\n26/08/2015",
    "note" => ""
  },
  "to_date" => %{
    "usage" => "to_date(date_str[, fmt]) - Parses the `date_str` expression with the `fmt` expression to\na date. Returns null with invalid input. By default, it follows casting rules to a date if\nthe `fmt` is omitted.",
    "examples" => "> SELECT to_date('2009-07-30 04:17:52');\n2009-07-30\n> SELECT to_date('2016-12-31', 'yyyy-MM-dd');\n2016-12-31",
    "note" => ""
  },
  "to_json" => %{
    "usage" => "to_json(expr[, options]) - Returns a JSON string with a given struct value",
    "examples" => "> SELECT to_json(named_struct('a', 1, 'b', 2));\n{\"a\":1,\"b\":2}\n> SELECT to_json(named_struct('time', to_timestamp('2015-08-26', 'yyyy-MM-dd')), map('timestampFormat', 'dd/MM/yyyy'));\n{\"time\":\"26/08/2015\"}\n> SELECT to_json(array(named_struct('a', 1, 'b', 2)));\n[{\"a\":1,\"b\":2}]\n> SELECT to_json(map('a', named_struct('b', 1)));\n{\"a\":{\"b\":1}}\n> SELECT to_json(map(named_struct('a', 1),named_struct('b', 2)));\n{\"[1]\":{\"b\":2}}\n> SELECT to_json(map('a', 1));\n{\"a\":1}\n> SELECT to_json(array(map('a', 1)));\n[{\"a\":1}]\n> SELECT to_json(named_struct('b', 1, 'a', 2), map('sortKeys', 'true'));\n{\"a\":2,\"b\":1}",
    "note" => ""
  },
  "to_number" => %{
    "usage" => "to_number(expr, fmt) - Convert string 'expr' to a number based on the string format 'fmt'.\nThrows an exception if the conversion fails. The format can consist of the following\ncharacters, case insensitive:\n'0' or '9': Specifies an expected digit between 0 and 9. A sequence of 0 or 9 in the format\nstring matches a sequence of digits in the input string. If the 0/9 sequence starts with\n0 and is before the decimal point, it can only match a digit sequence of the same size.\nOtherwise, if the sequence starts with 9 or is after the decimal point, it can match a\ndigit sequence that has the same or smaller size.\n'.' or 'D': Specifies the position of the decimal point (optional, only allowed once).\n',' or 'G': Specifies the position of the grouping (thousands) separator (,). There must be\na 0 or 9 to the left and right of each grouping separator. 'expr' must match the\ngrouping separator relevant for the size of the number.\n'$': Specifies the location of the $ currency sign. This character may only be specified\nonce.\n'S' or 'MI': Specifies the position of a '-' or '+' sign (optional, only allowed once at\nthe beginning or end of the format string). Note that 'S' allows '-' but 'MI' does not.\n'PR': Only allowed at the end of the format string; specifies that 'expr' indicates a\nnegative number with wrapping angled brackets.\n('<1>').",
    "examples" => "> SELECT to_number('454', '999');\n454\n> SELECT to_number('454.00', '000.00');\n454.00\n> SELECT to_number('12,454', '99,999');\n12454\n> SELECT to_number('$78.12', '$99.99');\n78.12\n> SELECT to_number('12,454.8-', '99,999.9S');\n-12454.8",
    "note" => ""
  },
  "to_time" => %{
    "usage" => "to_time(str[, format]) - Parses the `str` expression with the `format` expression to a time.\nIf `format` is malformed or its application does not result in a well formed time, the function\nraises an error. By default, it follows casting rules to a time if the `format` is omitted.",
    "examples" => "> SELECT to_time('00:12:00');\n00:12:00\n> SELECT to_time('12.10.05', 'HH.mm.ss');\n12:10:05",
    "note" => ""
  },
  "to_timestamp" => %{
    "usage" => "to_timestamp(timestamp_str[, fmt]) - Parses the `timestamp_str` expression with the `fmt` expression\nto a timestamp. Returns null with invalid input. By default, it follows casting rules to\na timestamp if the `fmt` is omitted. The result data type is consistent with the value of\nconfiguration `spark.sql.timestampType`.",
    "examples" => "> SELECT to_timestamp('2016-12-31 00:12:00');\n2016-12-31 00:12:00\n> SELECT to_timestamp('2016-12-31', 'yyyy-MM-dd');\n2016-12-31 00:00:00",
    "note" => ""
  },
  "to_timestamp_ltz" => %{
    "usage" => "to_timestamp_ltz(timestamp_str[, fmt]) - Parses the `timestamp_str` expression with the `fmt` expression\nto a timestamp with local time zone. Returns null with invalid input. By default, it follows casting rules to\na timestamp if the `fmt` is omitted.",
    "examples" => "> SELECT to_timestamp_ltz('2016-12-31 00:12:00');\n2016-12-31 00:12:00\n> SELECT to_timestamp_ltz('2016-12-31', 'yyyy-MM-dd');\n2016-12-31 00:00:00",
    "note" => ""
  },
  "to_timestamp_ntz" => %{
    "usage" => "to_timestamp_ntz(timestamp_str[, fmt]) - Parses the `timestamp_str` expression with the `fmt` expression\nto a timestamp without time zone. Returns null with invalid input. By default, it follows casting rules to\na timestamp if the `fmt` is omitted.",
    "examples" => "> SELECT to_timestamp_ntz('2016-12-31 00:12:00');\n2016-12-31 00:12:00\n> SELECT to_timestamp_ntz('2016-12-31', 'yyyy-MM-dd');\n2016-12-31 00:00:00",
    "note" => ""
  },
  "to_unix_timestamp" => %{
    "usage" => "to_unix_timestamp(timeExp[, fmt]) - Returns the UNIX timestamp of the given time.",
    "examples" => "> SELECT to_unix_timestamp('2016-04-08', 'yyyy-MM-dd');\n1460098800",
    "note" => ""
  },
  "to_utc_timestamp" => %{
    "usage" => "to_utc_timestamp(timestamp, timezone) - Given a timestamp like '2017-07-14 02:40:00.0', interprets it as a time in the given time zone, and renders that time as a timestamp in UTC. For example, 'GMT+1' would yield '2017-07-14 01:40:00.0'.",
    "examples" => "> SELECT to_utc_timestamp('2016-08-31', 'Asia/Seoul');\n2016-08-30 15:00:00",
    "note" => ""
  },
  "to_varchar" => %{
    "usage" => "to_varchar(expr, format) - Convert `expr` to a string based on the `format`.\nThrows an exception if the conversion fails. The format can consist of the following\ncharacters, case insensitive:\n'0' or '9': Specifies an expected digit between 0 and 9. A sequence of 0 or 9 in the format\nstring matches a sequence of digits in the input value, generating a result string of the\nsame length as the corresponding sequence in the format string. The result string is\nleft-padded with zeros if the 0/9 sequence comprises more digits than the matching part of\nthe decimal value, starts with 0, and is before the decimal point. Otherwise, it is\npadded with spaces.\n'.' or 'D': Specifies the position of the decimal point (optional, only allowed once).\n',' or 'G': Specifies the position of the grouping (thousands) separator (,). There must be\na 0 or 9 to the left and right of each grouping separator.\n'$': Specifies the location of the $ currency sign. This character may only be specified\nonce.\n'S' or 'MI': Specifies the position of a '-' or '+' sign (optional, only allowed once at\nthe beginning or end of the format string). Note that 'S' prints '+' for positive values\nbut 'MI' prints a space.\n'PR': Only allowed at the end of the format string; specifies that the result string will be\nwrapped by angle brackets if the input value is negative.\n('<1>').\nIf `expr` is a datetime, `format` shall be a valid datetime pattern, see <a href=\"https://spark.apache.org/docs/latest/sql-ref-datetime-pattern.html\">Datetime Patterns</a>.\nIf `expr` is a binary, it is converted to a string in one of the formats:\n'base64': a base 64 string.\n'hex': a string in the hexadecimal format.\n'utf-8': the input binary is decoded to UTF-8 string.",
    "examples" => "> SELECT to_varchar(454, '999');\n454\n> SELECT to_varchar(454.00, '000D00');\n454.00\n> SELECT to_varchar(12454, '99G999');\n12,454\n> SELECT to_varchar(78.12, '$99.99');\n$78.12\n> SELECT to_varchar(-12454.8, '99G999D9S');\n12,454.8-\n> SELECT to_varchar(date'2016-04-08', 'y');\n2016\n> SELECT to_varchar(x'537061726b2053514c', 'base64');\nU3BhcmsgU1FM\n> SELECT to_varchar(x'537061726b2053514c', 'hex');\n537061726B2053514C\n> SELECT to_varchar(encode('abc', 'utf-8'), 'utf-8');\nabc",
    "note" => ""
  },
  "to_variant_object" => %{
    "usage" => "to_variant_object(expr) - Convert a nested input (array/map/struct) into a variant where maps and structs are converted to variant objects which are unordered unlike SQL structs. Input maps can only have string keys.",
    "examples" => "> SELECT to_variant_object(named_struct('a', 1, 'b', 2));\n{\"a\":1,\"b\":2}\n> SELECT to_variant_object(array(1, 2, 3));\n[1,2,3]\n> SELECT to_variant_object(array(named_struct('a', 1)));\n[{\"a\":1}]\n> SELECT to_variant_object(array(map(\"a\", 2)));\n[{\"a\":2}]",
    "note" => ""
  },
  "to_xml" => %{
    "usage" => "to_xml(expr[, options]) - Returns a XML string with a given struct value",
    "examples" => "> SELECT to_xml(named_struct('a', 1, 'b', 2));\n<ROW>\n<a>1</a>\n<b>2</b>\n</ROW>\n> SELECT to_xml(named_struct('time', to_timestamp('2015-08-26', 'yyyy-MM-dd')), map('timestampFormat', 'dd/MM/yyyy'));\n<ROW>\n<time>26/08/2015</time>\n</ROW>",
    "note" => ""
  },
  "transform" => %{
    "usage" => "transform(expr, func) - Transforms elements in an array using the function.",
    "examples" => "> SELECT transform(array(1, 2, 3), x -> x + 1);\n[2,3,4]\n> SELECT transform(array(1, 2, 3), (x, i) -> x + i);\n[1,3,5]",
    "note" => ""
  },
  "transform_keys" => %{
    "usage" => "transform_keys(expr, func) - Transforms elements in a map using the function.",
    "examples" => "> SELECT transform_keys(map_from_arrays(array(1, 2, 3), array(1, 2, 3)), (k, v) -> k + 1);\n{2:1,3:2,4:3}\n> SELECT transform_keys(map_from_arrays(array(1, 2, 3), array(1, 2, 3)), (k, v) -> k + v);\n{2:1,4:2,6:3}",
    "note" => ""
  },
  "transform_values" => %{
    "usage" => "transform_values(expr, func) - Transforms values in the map using the function.",
    "examples" => "> SELECT transform_values(map_from_arrays(array(1, 2, 3), array(1, 2, 3)), (k, v) -> v + 1);\n{1:2,2:3,3:4}\n> SELECT transform_values(map_from_arrays(array(1, 2, 3), array(1, 2, 3)), (k, v) -> k + v);\n{1:2,2:4,3:6}",
    "note" => ""
  },
  "translate" => %{
    "usage" => "translate(input, from, to) - Translates the `input` string by replacing the characters present in the `from` string with the corresponding characters in the `to` string.",
    "examples" => "> SELECT translate('AaBbCc', 'abc', '123');\nA1B2C3",
    "note" => ""
  },
  "trim" => %{
    "usage" => "trim(str) - Removes the leading and trailing space characters from `str`.\ntrim(BOTH FROM str) - Removes the leading and trailing space characters from `str`.\ntrim(LEADING FROM str) - Removes the leading space characters from `str`.\ntrim(TRAILING FROM str) - Removes the trailing space characters from `str`.\ntrim(trimStr FROM str) - Remove the leading and trailing `trimStr` characters from `str`.\ntrim(BOTH trimStr FROM str) - Remove the leading and trailing `trimStr` characters from `str`.\ntrim(LEADING trimStr FROM str) - Remove the leading `trimStr` characters from `str`.\ntrim(TRAILING trimStr FROM str) - Remove the trailing `trimStr` characters from `str`.",
    "examples" => "> SELECT trim('    SparkSQL   ');\nSparkSQL\n> SELECT trim(BOTH FROM '    SparkSQL   ');\nSparkSQL\n> SELECT trim(LEADING FROM '    SparkSQL   ');\nSparkSQL\n> SELECT trim(TRAILING FROM '    SparkSQL   ');\nSparkSQL\n> SELECT trim('SL' FROM 'SSparkSQLS');\nparkSQ\n> SELECT trim(BOTH 'SL' FROM 'SSparkSQLS');\nparkSQ\n> SELECT trim(LEADING 'SL' FROM 'SSparkSQLS');\nparkSQLS\n> SELECT trim(TRAILING 'SL' FROM 'SSparkSQLS');\nSSparkSQ",
    "note" => ""
  },
  "trunc" => %{
    "usage" => "trunc(date, fmt) - Returns `date` with the time portion of the day truncated to the unit specified by the format model `fmt`.",
    "examples" => "> SELECT trunc('2019-08-04', 'week');\n2019-07-29\n> SELECT trunc('2019-08-04', 'quarter');\n2019-07-01\n> SELECT trunc('2009-02-12', 'MM');\n2009-02-01\n> SELECT trunc('2015-10-27', 'YEAR');\n2015-01-01",
    "note" => ""
  },
  "try_add" => %{
    "usage" => "try_add(expr1, expr2) - Returns the sum of `expr1`and `expr2` and the result is null on overflow. The acceptable input types are the same with the `+` operator.",
    "examples" => "> SELECT try_add(1, 2);\n3\n> SELECT try_add(2147483647, 1);\nNULL\n> SELECT try_add(date'2021-01-01', 1);\n2021-01-02\n> SELECT try_add(date'2021-01-01', interval 1 year);\n2022-01-01\n> SELECT try_add(timestamp'2021-01-01 00:00:00', interval 1 day);\n2021-01-02 00:00:00\n> SELECT try_add(interval 1 year, interval 2 year);\n3-0",
    "note" => ""
  },
  "try_aes_decrypt" => %{
    "usage" => "try_aes_decrypt(expr, key[, mode[, padding[, aad]]]) - This is a special version of `aes_decrypt` that performs the same operation, but returns a NULL value instead of raising an error if the decryption cannot be performed.",
    "examples" => "> SELECT try_aes_decrypt(unhex('6E7CA17BBB468D3084B5744BCA729FB7B2B7BCB8E4472847D02670489D95FA97DBBA7D3210'), '0000111122223333', 'GCM');\nSpark SQL\n> SELECT try_aes_decrypt(unhex('----------468D3084B5744BCA729FB7B2B7BCB8E4472847D02670489D95FA97DBBA7D3210'), '0000111122223333', 'GCM');\nNULL",
    "note" => ""
  },
  "try_avg" => %{
    "usage" => "try_avg(expr) - Returns the mean calculated from values of a group and the result is null on overflow.",
    "examples" => "> SELECT try_avg(col) FROM VALUES (1), (2), (3) AS tab(col);\n2.0\n> SELECT try_avg(col) FROM VALUES (1), (2), (NULL) AS tab(col);\n1.5\n> SELECT try_avg(col) FROM VALUES (interval '2147483647 months'), (interval '1 months') AS tab(col);\nNULL",
    "note" => ""
  },
  "try_divide" => %{
    "usage" => "try_divide(dividend, divisor) - Returns `dividend`/`divisor`. It always performs floating point division. Its result is always null if `expr2` is 0. `dividend` must be a numeric or an interval. `divisor` must be a numeric.",
    "examples" => "> SELECT try_divide(3, 2);\n1.5\n> SELECT try_divide(2L, 2L);\n1.0\n> SELECT try_divide(1, 0);\nNULL\n> SELECT try_divide(interval 2 month, 2);\n0-1\n> SELECT try_divide(interval 2 month, 0);\nNULL",
    "note" => ""
  },
  "try_element_at" => %{
    "usage" => "try_element_at(array, index) - Returns element of array at given (1-based) index. If Index is 0,\nSpark will throw an error. If index < 0, accesses elements from the last to the first.\nThe function always returns NULL if the index exceeds the length of the array.\ntry_element_at(map, key) - Returns value for given key. The function always returns NULL\nif the key is not contained in the map.",
    "examples" => "> SELECT try_element_at(array(1, 2, 3), 2);\n2\n> SELECT try_element_at(map(1, 'a', 2, 'b'), 2);\nb",
    "note" => ""
  },
  "try_make_interval" => %{
    "usage" => "try_make_interval([years[, months[, weeks[, days[, hours[, mins[, secs]]]]]]]) - This is a special version of `make_interval` that performs the same operation, but returns NULL when an overflow occurs.",
    "examples" => "> SELECT try_make_interval(100, 11, 1, 1, 12, 30, 01.001001);\n100 years 11 months 8 days 12 hours 30 minutes 1.001001 seconds\n> SELECT try_make_interval(100, null, 3);\nNULL\n> SELECT try_make_interval(0, 1, 0, 1, 0, 0, 100.000001);\n1 months 1 days 1 minutes 40.000001 seconds\n> SELECT try_make_interval(2147483647);\nNULL",
    "note" => ""
  },
  "try_make_timestamp_ltz" => %{
    "usage" => "try_make_timestamp_ltz(year, month, day, hour, min, sec[, timezone]) - Try to create the current timestamp with local time zone from year, month, day, hour, min, sec and (optional) timezone fields. The function returns NULL on invalid inputs.\ntry_make_timestamp_ltz(date, time[, timezone]) - Try to create the current timestamp with local time zone from date, time and (optional) timezone fields.",
    "examples" => "> SELECT try_make_timestamp_ltz(2014, 12, 28, 6, 30, 45.887);\n2014-12-28 06:30:45.887\n> SELECT try_make_timestamp_ltz(2014, 12, 28, 6, 30, 45.887, 'CET');\n2014-12-27 21:30:45.887\n> SELECT try_make_timestamp_ltz(2019, 6, 30, 23, 59, 60);\n2019-07-01 00:00:00\n> SELECT try_make_timestamp_ltz(null, 7, 22, 15, 30, 0);\nNULL\n> SELECT try_make_timestamp_ltz(2024, 13, 22, 15, 30, 0);\nNULL\n> SELECT try_make_timestamp_ltz(DATE'2014-12-28', TIME'6:30:45.887');\n2014-12-28 06:30:45.887\n> SELECT try_make_timestamp_ltz(DATE'2014-12-28', TIME'6:30:45.887', 'CET');\n2014-12-27 21:30:45.887",
    "note" => ""
  },
  "try_mod" => %{
    "usage" => "try_mod(dividend, divisor) - Returns the remainder after `expr1`/`expr2`. `dividend` must be a numeric. `divisor` must be a numeric.",
    "examples" => "> SELECT try_mod(3, 2);\n1\n> SELECT try_mod(2L, 2L);\n0\n> SELECT try_mod(3.0, 2.0);\n1.0\n> SELECT try_mod(1, 0);\nNULL",
    "note" => ""
  },
  "try_multiply" => %{
    "usage" => "try_multiply(expr1, expr2) - Returns `expr1`*`expr2` and the result is null on overflow. The acceptable input types are the same with the `*` operator.",
    "examples" => "> SELECT try_multiply(2, 3);\n6\n> SELECT try_multiply(-2147483648, 10);\nNULL\n> SELECT try_multiply(interval 2 year, 3);\n6-0",
    "note" => ""
  },
  "try_parse_json" => %{
    "usage" => "try_parse_json(jsonStr) - Parse a JSON string as a Variant value. Return NULL when the string is not valid JSON value.",
    "examples" => "> SELECT try_parse_json('{\"a\":1,\"b\":0.8}');\n{\"a\":1,\"b\":0.8}\n> SELECT try_parse_json('{\"a\":1,');\nNULL",
    "note" => ""
  },
  "try_parse_url" => %{
    "usage" => "try_parse_url(url, partToExtract[, key]) - This is a special version of `parse_url` that performs the same operation, but returns a NULL value instead of raising an error if the parsing cannot be performed.",
    "examples" => "> SELECT try_parse_url('http://spark.apache.org/path?query=1', 'HOST');\nspark.apache.org\n> SELECT try_parse_url('http://spark.apache.org/path?query=1', 'QUERY');\nquery=1\n> SELECT try_parse_url('inva lid://spark.apache.org/path?query=1', 'QUERY');\nNULL\n> SELECT try_parse_url('http://spark.apache.org/path?query=1', 'QUERY', 'query');\n1",
    "note" => ""
  },
  "try_reflect" => %{
    "usage" => "try_reflect(class, method[, arg1[, arg2 ..]]) - This is a special version of `reflect` that performs the same operation, but returns a NULL value instead of raising an error if the invoke method thrown exception.",
    "examples" => "> SELECT try_reflect('java.util.UUID', 'randomUUID');\nc33fb387-8500-4bfa-81d2-6e0e3e930df2\n> SELECT try_reflect('java.util.UUID', 'fromString', 'a5cf6c42-0c85-418f-af6c-3e4e5b1328f2');\na5cf6c42-0c85-418f-af6c-3e4e5b1328f2\n> SELECT try_reflect('java.net.URLDecoder', 'decode', '%');\nNULL",
    "note" => ""
  },
  "try_subtract" => %{
    "usage" => "try_subtract(expr1, expr2) - Returns `expr1`-`expr2` and the result is null on overflow. The acceptable input types are the same with the `-` operator.",
    "examples" => "> SELECT try_subtract(2, 1);\n1\n> SELECT try_subtract(-2147483648, 1);\nNULL\n> SELECT try_subtract(date'2021-01-02', 1);\n2021-01-01\n> SELECT try_subtract(date'2021-01-01', interval 1 year);\n2020-01-01\n> SELECT try_subtract(timestamp'2021-01-02 00:00:00', interval 1 day);\n2021-01-01 00:00:00\n> SELECT try_subtract(interval 2 year, interval 1 year);\n1-0",
    "note" => ""
  },
  "try_sum" => %{
    "usage" => "try_sum(expr) - Returns the sum calculated from values of a group and the result is null on overflow.",
    "examples" => "> SELECT try_sum(col) FROM VALUES (5), (10), (15) AS tab(col);\n30\n> SELECT try_sum(col) FROM VALUES (NULL), (10), (15) AS tab(col);\n25\n> SELECT try_sum(col) FROM VALUES (NULL), (NULL) AS tab(col);\nNULL\n> SELECT try_sum(col) FROM VALUES (9223372036854775807L), (1L) AS tab(col);\nNULL",
    "note" => ""
  },
  "try_to_binary" => %{
    "usage" => "try_to_binary(str[, fmt]) - This is a special version of `to_binary` that performs the same operation, but returns a NULL value instead of raising an error if the conversion cannot be performed.",
    "examples" => "> SELECT try_to_binary('abc', 'utf-8');\nabc\n> select try_to_binary('a!', 'base64');\nNULL\n> select try_to_binary('abc', 'invalidFormat');\nNULL",
    "note" => ""
  },
  "try_to_date" => %{
    "usage" => "try_to_date(date_str[, fmt]) - Parses the `date_str` expression with the `fmt` expression to a date.\nThe function always returns null on an invalid input with/without ANSI SQL mode enabled. By\ndefault, it follows casting rules to a date if the `fmt` is omitted.",
    "examples" => "> SELECT try_to_date('2016-12-31');\n2016-12-31\n> SELECT try_to_date('2016-12-31', 'yyyy-MM-dd');\n2016-12-31\n> SELECT try_to_date('foo', 'yyyy-MM-dd');\nNULL",
    "note" => ""
  },
  "try_to_number" => %{
    "usage" => "try_to_number(expr, fmt) - Convert string 'expr' to a number based on the string format `fmt`.\nReturns NULL if the string 'expr' does not match the expected format. The format follows the\nsame semantics as the to_number function.",
    "examples" => "> SELECT try_to_number('454', '999');\n454\n> SELECT try_to_number('454.00', '000.00');\n454.00\n> SELECT try_to_number('12,454', '99,999');\n12454\n> SELECT try_to_number('$78.12', '$99.99');\n78.12\n> SELECT try_to_number('12,454.8-', '99,999.9S');\n-12454.8",
    "note" => ""
  },
  "try_to_time" => %{
    "usage" => "try_to_time(str[, format]) - Parses the `str` expression with the `format` expression to a time.\nIf `format` is malformed or its application does not result in a well formed time, the function\nreturns NULL. By default, it follows casting rules to a time if the `format` is omitted.",
    "examples" => "> SELECT try_to_time('00:12:00.001');\n00:12:00.001\n> SELECT try_to_time('12.10.05.999999', 'HH.mm.ss.SSSSSS');\n12:10:05.999999\n> SELECT try_to_time('foo', 'HH:mm:ss');\nNULL",
    "note" => ""
  },
  "try_to_timestamp" => %{
    "usage" => "try_to_timestamp(timestamp_str[, fmt]) - Parses the `timestamp_str` expression with the `fmt` expression\nto a timestamp. The function always returns null on an invalid input with/without ANSI SQL\nmode enabled. By default, it follows casting rules to a timestamp if the `fmt` is omitted.\nThe result data type is consistent with the value of configuration `spark.sql.timestampType`.",
    "examples" => "> SELECT try_to_timestamp('2016-12-31 00:12:00');\n2016-12-31 00:12:00\n> SELECT try_to_timestamp('2016-12-31', 'yyyy-MM-dd');\n2016-12-31 00:00:00\n> SELECT try_to_timestamp('foo', 'yyyy-MM-dd');\nNULL",
    "note" => ""
  },
  "try_url_decode" => %{
    "usage" => "try_url_decode(str) - This is a special version of `url_decode` that performs the same operation, but returns a NULL value instead of raising an error if the decoding cannot be performed.",
    "examples" => "> SELECT try_url_decode('https%3A%2F%2Fspark.apache.org');\nhttps://spark.apache.org",
    "note" => ""
  },
  "try_validate_utf8" => %{
    "usage" => "try_validate_utf8(str) - Returns the original string if `str` is a valid UTF-8 string, otherwise returns NULL.",
    "examples" => "> SELECT try_validate_utf8('Spark');\nSpark\n> SELECT try_validate_utf8(x'61');\na\n> SELECT try_validate_utf8(x'80');\nNULL\n> SELECT try_validate_utf8(x'61C262');\nNULL",
    "note" => ""
  },
  "try_variant_get" => %{
    "usage" => "try_variant_get(v, path[, type]) - Extracts a sub-variant from `v` according to `path`, and then cast the sub-variant to `type`. When `type` is omitted, it is default to `variant`. Returns null if the path does not exist or the cast fails.",
    "examples" => "> SELECT try_variant_get(parse_json('{\"a\": 1}'), '$.a', 'int');\n1\n> SELECT try_variant_get(parse_json('{\"a\": 1}'), '$.b', 'int');\nNULL\n> SELECT try_variant_get(parse_json('[1, \"2\"]'), '$[1]', 'string');\n2\n> SELECT try_variant_get(parse_json('[1, \"2\"]'), '$[2]', 'string');\nNULL\n> SELECT try_variant_get(parse_json('[1, \"hello\"]'), '$[1]');\n\"hello\"\n> SELECT try_variant_get(parse_json('[1, \"hello\"]'), '$[1]', 'int');\nNULL",
    "note" => ""
  },
  "tuple_difference_double" => %{
    "usage" => "tuple_difference_double(tupleSketch1, tupleSketch2) - Subtracts two binary representations of Datasketches\nTupleSketch objects with double summary data type using a TupleSketch AnotB object.\nReturns elements in the first sketch that are not in the second sketch.",
    "examples" => "> SELECT tuple_sketch_estimate_double(tuple_difference_double(tuple_sketch_agg_double(col1, val1), tuple_sketch_agg_double(col2, val2))) FROM VALUES (5, 5.0D, 4, 4.0D), (1, 1.0D, 4, 4.0D), (2, 2.0D, 5, 5.0D), (3, 3.0D, 1, 1.0D) tab(col1, val1, col2, val2);\n2.0",
    "note" => ""
  },
  "tuple_difference_integer" => %{
    "usage" => "tuple_difference_integer(tupleSketch1, tupleSketch2) - Subtracts two binary representations of Datasketches\nTupleSketch objects with integer summary data type using a TupleSketch AnotB object.\nReturns elements in the first sketch that are not in the second sketch.",
    "examples" => "> SELECT tuple_sketch_estimate_integer(tuple_difference_integer(tuple_sketch_agg_integer(col1, val1), tuple_sketch_agg_integer(col2, val2))) FROM VALUES (5, 5, 4, 4), (1, 1, 4, 4), (2, 2, 5, 5), (3, 3, 1, 1) tab(col1, val1, col2, val2);\n2.0",
    "note" => ""
  },
  "tuple_difference_theta_double" => %{
    "usage" => "tuple_difference_theta_double(tupleSketch, thetaSketch) - Subtracts the binary representation of a\nDatasketches ThetaSketch from a TupleSketch with double summary data type using a TupleSketch\nAnotB object. Returns elements in the TupleSketch that are not in the ThetaSketch.",
    "examples" => "> SELECT tuple_sketch_estimate_double(tuple_difference_theta_double(tuple_sketch_agg_double(col1, val1), theta_sketch_agg(col2))) FROM VALUES (5, 5.0D, 4), (1, 1.0D, 4), (2, 2.0D, 5), (3, 3.0D, 1) tab(col1, val1, col2);\n2.0",
    "note" => ""
  },
  "tuple_difference_theta_integer" => %{
    "usage" => "tuple_difference_theta_integer(tupleSketch, thetaSketch) - Subtracts the binary representation of a\nDatasketches ThetaSketch from a TupleSketch with integer summary data type using a TupleSketch\nAnotB object. Returns elements in the TupleSketch that are not in the ThetaSketch.",
    "examples" => "> SELECT tuple_sketch_estimate_integer(tuple_difference_theta_integer(tuple_sketch_agg_integer(col1, val1), theta_sketch_agg(col2))) FROM VALUES (5, 5, 4), (1, 1, 4), (2, 2, 5), (3, 3, 1) tab(col1, val1, col2);\n2.0",
    "note" => ""
  },
  "tuple_sketch_theta_double" => %{
    "usage" => "tuple_sketch_theta_double(child) - Returns the theta value (sampling rate) from a Datasketches TupleSketch.\nThe theta value represents the effective sampling rate of the sketch, between 0.0 and 1.0.\nThe sketch's summary type must be a double.",
    "examples" => "> SELECT tuple_sketch_theta_double(tuple_sketch_agg_double(key, summary)) FROM VALUES (1, 1.0D), (2, 2.0D), (3, 3.0D) tab(key, summary);\n1.0",
    "note" => ""
  },
  "tuple_sketch_theta_integer" => %{
    "usage" => "tuple_sketch_theta_integer(child) - Returns the theta value (sampling rate) from a Datasketches TupleSketch.\nThe theta value represents the effective sampling rate of the sketch, between 0.0 and 1.0.\nThe sketch's summary type must be an integer.",
    "examples" => "> SELECT tuple_sketch_theta_integer(tuple_sketch_agg_integer(key, summary)) FROM VALUES (1, 1), (2, 2), (3, 3) tab(key, summary);\n1.0",
