  "uniform" => %{
    "usage" => "uniform(min, max[, seed]) - Returns a random value with independent and identically\ndistributed (i.i.d.) values with the specified range of numbers. The random seed is optional.\nThe provided numbers specifying the minimum and maximum values of the range must be constant.\nIf both of these numbers are integers, then the result will also be an integer. Otherwise if\none or both of these are floating-point numbers, then the result will also be a floating-point\nnumber.",
    "examples" => "> SELECT uniform(10, 20, 0) > 0 AS result;\ntrue",
    "note" => ""
  },
  "unix_date" => %{
