  },
  "variant_get" => %{
    "usage" => "variant_get(v, path[, type]) - Extracts a sub-variant from `v` according to `path`, and then cast the sub-variant to `type`. When `type` is omitted, it is default to `variant`. Returns null if the path does not exist. Throws an exception if the cast fails.",
    "examples" => "> SELECT variant_get(parse_json('{\"a\": 1}'), '$.a', 'int');\n1\n> SELECT variant_get(parse_json('{\"a\": 1}'), '$.b', 'int');\nNULL\n> SELECT variant_get(parse_json('[1, \"2\"]'), '$[1]', 'string');\n2\n> SELECT variant_get(parse_json('[1, \"2\"]'), '$[2]', 'string');\nNULL\n> SELECT variant_get(parse_json('[1, \"hello\"]'), '$[1]');\n\"hello\"",
    "note" => ""
  },
  "version" => %{
    "usage" => "version() - Returns the Spark version. The string contains 2 fields, the first being a release version and the second being a git revision.",
    "examples" => "> SELECT version();\n3.1.0 a6d6ea3efedbad14d99c24143834cd4e2e52fb40",
    "note" => ""
  },
  "weekday" => %{
    "usage" => "weekday(date) - Returns the day of the week for date/timestamp (0 = Monday, 1 = Tuesday, ..., 6 = Sunday).",
    "examples" => "> SELECT weekday('2009-07-30');\n3",
    "note" => ""
  },
  "weekofyear" => %{
    "usage" => "weekofyear(date) - Returns the week of the year of the given date. A week is considered to start on a Monday and week 1 is the first week with >3 days.",
    "examples" => "> SELECT weekofyear('2008-02-20');\n8",
    "note" => ""
  },
  "width_bucket" => %{
    "usage" => "width_bucket(value, min_value, max_value, num_bucket) - Returns the bucket number to which\n`value` would be assigned in an equiwidth histogram with `num_bucket` buckets,\nin the range `min_value` to `max_value`.\"",
    "examples" => "> SELECT width_bucket(5.3, 0.2, 10.6, 5);\n3\n> SELECT width_bucket(-2.1, 1.3, 3.4, 3);\n0\n> SELECT width_bucket(8.1, 0.0, 5.7, 4);\n5\n> SELECT width_bucket(-0.9, 5.2, 0.5, 2);\n3\n> SELECT width_bucket(INTERVAL '0' YEAR, INTERVAL '0' YEAR, INTERVAL '10' YEAR, 10);\n1\n> SELECT width_bucket(INTERVAL '1' YEAR, INTERVAL '0' YEAR, INTERVAL '10' YEAR, 10);\n2\n> SELECT width_bucket(INTERVAL '0' DAY, INTERVAL '0' DAY, INTERVAL '10' DAY, 10);\n1\n> SELECT width_bucket(INTERVAL '1' DAY, INTERVAL '0' DAY, INTERVAL '10' DAY, 10);\n2",
    "note" => ""
  },
  "window" => %{
    "usage" => "window(time_column, window_duration[, slide_duration[, start_time]]) - Bucketize rows into one or more time windows given a timestamp specifying column.\nWindow starts are inclusive but the window ends are exclusive, e.g. 12:05 will be in the window [12:05,12:10) but not in [12:00,12:05).\nWindows can support microsecond precision. Windows in the order of months are not supported.\nSee <a href=\"https://spark.apache.org/docs/latest/structured-streaming-programming-guide.html#window-operations-on-event-time\">'Window Operations on Event Time'</a> in Structured Streaming guide doc for detailed explanation and examples.",
    "examples" => "> SELECT a, window.start, window.end, count(*) as cnt FROM VALUES ('A1', '2021-01-01 00:00:00'), ('A1', '2021-01-01 00:04:30'), ('A1', '2021-01-01 00:06:00'), ('A2', '2021-01-01 00:01:00') AS tab(a, b) GROUP by a, window(b, '5 minutes') ORDER BY a, start;\nA1\t2021-01-01 00:00:00\t2021-01-01 00:05:00\t2\nA1\t2021-01-01 00:05:00\t2021-01-01 00:10:00\t1\nA2\t2021-01-01 00:00:00\t2021-01-01 00:05:00\t1\n> SELECT a, window.start, window.end, count(*) as cnt FROM VALUES ('A1', '2021-01-01 00:00:00'), ('A1', '2021-01-01 00:04:30'), ('A1', '2021-01-01 00:06:00'), ('A2', '2021-01-01 00:01:00') AS tab(a, b) GROUP by a, window(b, '10 minutes', '5 minutes') ORDER BY a, start;\nA1\t2020-12-31 23:55:00\t2021-01-01 00:05:00\t2\nA1\t2021-01-01 00:00:00\t2021-01-01 00:10:00\t3\nA1\t2021-01-01 00:05:00\t2021-01-01 00:15:00\t1\nA2\t2020-12-31 23:55:00\t2021-01-01 00:05:00\t1\nA2\t2021-01-01 00:00:00\t2021-01-01 00:10:00\t1",
    "note" => ""
  },
  "window_time" => %{
    "usage" => "window_time(window_column) - Extract the time value from time/session window column which can be used for event time value of window.\nThe extracted time is (window.end - 1) which reflects the fact that the aggregating\nwindows have exclusive upper bound - [start, end)\nSee <a href=\"https://spark.apache.org/docs/latest/structured-streaming-programming-guide.html#window-operations-on-event-time\">'Window Operations on Event Time'</a> in Structured Streaming guide doc for detailed explanation and examples.",
    "examples" => "> SELECT a, window.start as start, window.end as end, window_time(window), cnt FROM (SELECT a, window, count(*) as cnt FROM VALUES ('A1', '2021-01-01 00:00:00'), ('A1', '2021-01-01 00:04:30'), ('A1', '2021-01-01 00:06:00'), ('A2', '2021-01-01 00:01:00') AS tab(a, b) GROUP by a, window(b, '5 minutes') ORDER BY a, window.start);\nA1\t2021-01-01 00:00:00\t2021-01-01 00:05:00\t2021-01-01 00:04:59.999999\t2\nA1\t2021-01-01 00:05:00\t2021-01-01 00:10:00\t2021-01-01 00:09:59.999999\t1\nA2\t2021-01-01 00:00:00\t2021-01-01 00:05:00\t2021-01-01 00:04:59.999999\t1",
    "note" => ""
  },
  "xpath" => %{
    "usage" => "xpath(xml, xpath) - Returns a string array of values within the nodes of xml that match the XPath expression.",
    "examples" => "> SELECT xpath('<a><b>b1</b><b>b2</b><b>b3</b><c>c1</c><c>c2</c></a>','a/b/text()');\n[\"b1\",\"b2\",\"b3\"]\n> SELECT xpath('<a><b>b1</b><b>b2</b><b>b3</b><c>c1</c><c>c2</c></a>','a/b');\n[null,null,null]",
    "note" => ""
