  },
  "xpath_string" => %{
    "usage" => "xpath_string(xml, xpath) - Returns the text contents of the first xml node that matches the XPath expression.",
    "examples" => "> SELECT xpath_string('<a><b>b</b><c>cc</c></a>','a/c');\ncc",
    "note" => ""
  },
  "xxhash64" => %{
    "usage" => "xxhash64(expr1, expr2, ...) - Returns a 64-bit hash value of the arguments. Hash seed is 42.",
    "examples" => "> SELECT xxhash64('Spark', array(123), 2);\n5602566077635097486",
    "note" => ""
  },
  "year" => %{
    "usage" => "year(date) - Returns the year component of the date/timestamp.",
    "examples" => "> SELECT year('2016-07-30');\n2016",
    "note" => ""
  },
  "zeroifnull" => %{
    "usage" => "zeroifnull(expr) - Returns zero if `expr` is equal to null, or `expr` otherwise.",
    "examples" => "> SELECT zeroifnull(NULL);\n0\n> SELECT zeroifnull(2);\n2",
    "note" => ""
  },
  "zip_with" => %{
    "usage" => "zip_with(left, right, func) - Merges the two given arrays, element-wise, into a single array using function. If one array is shorter, nulls are appended at the end to match the length of the longer array, before applying function.",
    "examples" => "> SELECT zip_with(array(1, 2, 3), array('a', 'b', 'c'), (x, y) -> (y, x));\n[{\"y\":\"a\",\"x\":1},{\"y\":\"b\",\"x\":2},{\"y\":\"c\",\"x\":3}]\n> SELECT zip_with(array(1, 2), array(3, 4), (x, y) -> x + y);\n[4,6]\n> SELECT zip_with(array('a', 'b', 'c'), array('d', 'e', 'f'), (x, y) -> concat(x, y));\n[\"ad\",\"be\",\"cf\"]",
    "note" => ""
  },
  "~" => %{
    "usage" => "~ expr - Returns the result of bitwise NOT of `expr`.",
    "examples" => "> SELECT ~ 0;\n-1",
    "note" => ""
  },
}
